// The film around every archive shot: the picture sits in a projector gate. Built from kit/looks (GateWeave, Flicker,
// Dust, WindowLight, EdgeBlur, Vignette) with the numbers of the reference's own presets:
//
//   Gate Weave & Exposure Flicker / GateWeave.ffx   Transform Position expression:
//       fps = 24; seedRandom(Math.floor(time * fps), true); jitter = 1.5; value + [random(-jitter, jitter), ...]
//     a new uniform offset in +-1.5 px each 1/24 s, x and y independent. `Weave` below is exactly that (scaled to W);
//     the reel itself measured on twos at std 1.1 / 1.7 px, which `GateWeave` reproduces:
//     pass weave="measured" for it.
//   Cinema Treatment / Secret Sauce.ffx   Add Grain, Posterize Time, an Exposure whose expression holds a random
//     value in +-0.04 stops for 1/2 s (freq = 2), and the same Transform weave. `Flicker` below stacks that slow
//     held flicker on the reel's measured per-frame one (0.024 stops, Da3YpRipHuF).
//   HeavyFlicker.ffx   Exposure wiggle(24, .2): `heavy` doubles the per-frame flicker for an older, rougher reel.
//
// Order, bottom to top, as in the reference project's stack: picture, edge blur, (window
// light), weave + flicker over all of that, then dust and the scanned film texture screened, then the vignette.
import React from 'react';
import { AbsoluteFill, Img, random, staticFile, useCurrentFrame, useVideoConfig } from 'remotion';
import { Dust, EdgeBlur, GateWeave, Vignette, WindowLight } from './shared/kit/looks/film.js';

const gauss = (seed: string) => ((random(`${seed}a`) + random(`${seed}b`) + random(`${seed}c`)) - 1.5) / 0.5;

/** The GateWeave.ffx preset: a new offset in +-`jitter` px (at 1080 wide) every 1/`rate` s. */
export const Weave: React.FC<{ jitter?: number; rate?: number; seed?: string; overscan?: number; children: React.ReactNode }> = ({ jitter = 1.5, rate = 24, seed = 'aw', overscan = 1.012, children }) => {
  const f = useCurrentFrame();
  const { fps, width: W } = useVideoConfig();
  const n = Math.floor((f / fps) * rate), k = W / 1080;
  const x = (random(`${seed}x${n}`) * 2 - 1) * jitter * k, y = (random(`${seed}y${n}`) * 2 - 1) * jitter * k;
  return <AbsoluteFill style={{ transform: `translate(${x.toFixed(2)}px, ${y.toFixed(2)}px) scale(${overscan})` }}>{children}</AbsoluteFill>;
};

/** Exposure flicker: Secret Sauce's held +-0.04 stops (new value every 1/2 s) times the measured per-frame 0.024. */
export const Flicker: React.FC<{ held?: number; holdHz?: number; stops?: number; heavy?: boolean; seed?: string; children: React.ReactNode }> = ({ held = 0.04, holdHz = 2, stops = 0.024, heavy, seed = 'afl', children }) => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const slow = (random(`${seed}h${Math.floor((f / fps) * holdHz)}`) * 2 - 1) * held;
  const fast = gauss(`${seed}${f}`) * stops * (heavy ? 2 : 1);
  return <AbsoluteFill style={{ filter: `brightness(${(2 ** (slow + fast)).toFixed(4)})` }}>{children}</AbsoluteFill>;
};

/** The scanned film texture (a Texturelabs scan, downscaled; tastes/archive/textures, linked into the effect's public
 *  folder as `archive-textures`): screened, its frame jumping every 2 frames so the scratches and specks move like
 *  film running through the gate. */
export const FilmScan: React.FC<{ strength?: number; base?: string }> = ({ strength = 0.5, base = 'archive-textures' }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const n = Math.floor(f / 2);
  const ox = random(`fsx${n}`), oy = random(`fsy${n}`), flip = random(`fsf${n}`) > 0.5;
  return (
    <AbsoluteFill style={{ pointerEvents: 'none', mixBlendMode: 'screen', opacity: strength, overflow: 'hidden' }}>
      {/* drawn larger than the frame, offset and mirrored at random each step */}
      <Img src={staticFile(`${base}/film-scan.jpg`)} style={{ position: 'absolute', width: W * 1.2, height: H * 1.2, left: -ox * W * 0.2, top: -oy * H * 0.2, objectFit: 'cover',
        transform: `scaleX(${flip ? -1 : 1})` }} />
    </AbsoluteFill>
  );
};

export interface FinishProps {
  /** the picture, made fresh for each id (the edge blur draws it a second time and needs its own layer ids) */
  picture: (copy: string) => React.ReactNode;
  /** slow push, scale per frame from `from` (DZFqNzwAqVa: about 0.2% a frame) */
  push?: number;
  from?: number;
  /** push pivot, fractions of the frame */
  pivot?: [number, number];
  /** the edge blur radius at 1080 wide (0 off) and the sharp centre */
  blur?: number;
  focus?: [number, number];
  /** window light multiplied over the picture (DdKZ5oBpPCW), 0 off */
  light?: number;
  lightAngle?: number;
  weave?: 'preset' | 'measured' | 'off';
  flicker?: boolean;
  heavy?: boolean;
  dust?: number;
  scan?: number;
  vignette?: number;
}

/** A finished archive shot: the picture with every film layer over it. */
export const ArchiveFinish: React.FC<FinishProps> = ({ picture, push = 0.0012, from = 0, pivot = [0.5, 0.42], blur = 40, focus = [0.5, 0.42], light = 0, lightAngle = -24, weave = 'preset', flicker = true, heavy, dust = 0.45, scan = 0.35, vignette = 1 }) => {
  const f = useCurrentFrame();
  const s = 1 + push * Math.max(0, f - from);
  let body: React.ReactNode = (
    <AbsoluteFill style={{ transform: `scale(${s.toFixed(4)})`, transformOrigin: `${pivot[0] * 100}% ${pivot[1] * 100}%` }}>
      {picture('a')}
      {blur > 0 && <EdgeBlur radius={blur} cx={focus[0]} cy={focus[1]}>{picture('b')}</EdgeBlur>}
      {light > 0 && <WindowLight strength={light} angle={lightAngle} drift={0.1} />}
    </AbsoluteFill>
  );
  if (weave === 'preset') body = <Weave>{body}</Weave>;
  if (weave === 'measured') body = <GateWeave>{body}</GateWeave>;
  if (flicker) body = <Flicker heavy={heavy}>{body}</Flicker>;
  return (
    <AbsoluteFill style={{ overflow: 'hidden', background: '#0d0b09' }}>
      {body}
      {dust > 0 && <Dust strength={dust} density={160} hairs={3} />}
      {scan > 0 && <FilmScan strength={scan} />}
      {vignette > 0 && <Vignette strength={vignette} />}
    </AbsoluteFill>
  );
};

// The archive taste: historical photographs brought to life (old-film documentary). See tokens.ts for the rules and
// the reels each comes from, README.md for when to use it.
export { ARCHIVE, FONTS, PROCESS, STEP } from './tokens.js';
export type { Process } from './tokens.js';
export { ArchivePhoto, Toned, toneEffect } from './photo.js';
export type { ToneProps } from './photo.js';
export { Dateline, Develop, Line, Scrim, Tag, serif, typewriter } from './type.js';
export { ArchiveFinish, FilmScan, Flicker, Weave } from './film.js';
export type { FinishProps } from './film.js';
export { AlbumPage, ParallaxPlate, PlateMat } from './layouts.js';
export type { Mounted, ParallaxPlateProps } from './layouts.js';
// the techniques it composes, re-exported so a reel needs one import
export { CurveCut, PageTurn, Parallax, Posterize, SPEED_SPIKE } from './shared/kit/looks/index.js';
export { Dust, EdgeBlur, GateWeave, Vignette, WindowLight } from './shared/kit/looks/film.js';

// Layouts made from the objects themselves:
//   PlateMat       a daguerreotype's brass mat (the window a plate sits behind in its case), as a foreground layer:
//                  use it as the near layer of a parallax (factor 3, defocused) and the camera slides past the mat
//   ParallaxPlate  a photo cut into layers (kit/looks Parallax, factors 3 : 1 : 0.6) with a slow push, on twos,
//                  printed as its process
//   AlbumPage      a page of a 19th-century album: card stock, prints mounted with photo corners, typed labels; the
//                  page to turn with kit/looks PageTurn (posterized to 8 fps)
import React from 'react';
import { AbsoluteFill, Img, useCurrentFrame, useVideoConfig } from 'remotion';
import { Parallax, type ParallaxLayer } from './shared/kit/looks/parallax.js';
import { Posterize } from './shared/kit/looks/posterize.js';
import { Toned, type ToneProps } from './photo.js';
import { ARCHIVE } from './tokens.js';
import { typewriter } from './type.js';

/** The brass mat of a cased daguerreotype, full frame, the window in the middle: an arched top, cut corners below,
 *  engraved bead lines, velvet outside. `window` is the opening in fractions of the frame. */
export const PlateMat: React.FC<{ window?: [number, number, number, number]; velvet?: boolean }> = ({ window: win = [0.09, 0.07, 0.91, 0.9], velvet = true }) => {
  const { width: W, height: H } = useVideoConfig();
  const [x0, y0, x1, y1] = [win[0] * W, win[1] * H, win[2] * W, win[3] * H];
  const r = (x1 - x0) / 2, c = 0.06 * W;
  // the opening: a semicircular arch on top, straight sides, cut corners at the bottom
  const open = `M${x0} ${y0 + r} A${r} ${r} 0 0 1 ${x1} ${y0 + r} L${x1} ${y1 - c} L${x1 - c} ${y1} L${x0 + c} ${y1} L${x0} ${y1 - c} Z`;
  const pad = 0.035 * W;
  const outer = `M${x0 - pad} ${y0 + r} A${r + pad} ${r + pad} 0 0 1 ${x1 + pad} ${y0 + r} L${x1 + pad} ${y1 - c + pad * 0.4} L${x1 - c + pad * 0.4} ${y1 + pad} L${x0 + c - pad * 0.4} ${y1 + pad} L${x0 - pad} ${y1 - c + pad * 0.4} Z`;
  return (
    <svg width={W} height={H} style={{ position: 'absolute', left: 0, top: 0 }}>
      <defs>
        <linearGradient id="brass" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#e4c27e" /><stop offset="0.35" stopColor={ARCHIVE.brass} /><stop offset="0.55" stopColor="#d6b06a" /><stop offset="0.8" stopColor={ARCHIVE.brassDark} /><stop offset="1" stopColor="#c59e5c" />
        </linearGradient>
        <radialGradient id="velvet" cx="0.5" cy="0.45" r="0.75"><stop offset="0.5" stopColor="#3a1a1d" /><stop offset="1" stopColor="#140708" /></radialGradient>
      </defs>
      {velvet && <path d={`M0 0 H${W} V${H} H0 Z ${outer}`} fillRule="evenodd" fill="url(#velvet)" />}
      <path d={`${outer} ${open}`} fillRule="evenodd" fill="url(#brass)" />
      {/* engraved bead lines and the tarnish at the window's edge */}
      <path d={outer} fill="none" stroke="rgba(60,40,10,0.55)" strokeWidth={0.003 * W} transform={`translate(${W / 2} ${H / 2}) scale(0.985) translate(${-W / 2} ${-H / 2})`} />
      <path d={open} fill="none" stroke="rgba(40,26,8,0.8)" strokeWidth={0.006 * W} />
      <path d={open} fill="none" stroke="rgba(255,236,190,0.5)" strokeWidth={0.002 * W} transform={`translate(${W / 2} ${H / 2}) scale(1.012) translate(${-W / 2} ${-H / 2})`} />
    </svg>
  );
};

export interface ParallaxPlateProps extends ToneProps {
  id: string;
  /** back to front: background (hole filled), subject cut-out, an optional near layer */
  layers: ParallaxLayer[];
  start: number;
  duration: number;
  travel?: number;
  rise?: number;
  /** a push over the move, scale per frame */
  push?: number;
  /** what the picture is framed on: position and zoom of every layer (they share it, so they stay registered) */
  zoom?: number;
  origin?: string;
  /** frames per step: 2 = on twos, as in the reference */
  step?: number;
  /** a near layer drawn untoned (a brass mat keeps its colour) */
  near?: React.ReactNode;
  nearFactor?: number;
  nearBlur?: number;
}

/** A photo cut into layers sliding in depth, printed as its process, on twos. */
export const ParallaxPlate: React.FC<ParallaxPlateProps> = ({ id, layers, start, duration, travel = -0.05, rise = 0, push = 0.0008, zoom = 1, origin = '50% 40%', step = 2, near, nearFactor = 3, nearBlur = 6, ...tone }) => {
  const f = useCurrentFrame();
  const s = zoom * (1 + push * Math.max(0, f - start));
  return (
    <Posterize step={step}>
      <AbsoluteFill style={{ overflow: 'hidden' }}>
        <Toned id={id} {...tone}>
          <AbsoluteFill style={{ transform: `scale(${s.toFixed(4)})`, transformOrigin: origin }}>
            <Parallax layers={layers} start={start} duration={duration} travel={travel} rise={rise} />
          </AbsoluteFill>
        </Toned>
        {near && <Parallax layers={[{ node: near, factor: nearFactor, blur: nearBlur }]} start={start} duration={duration} travel={travel} rise={rise} />}
      </AbsoluteFill>
    </Posterize>
  );
};

export interface Mounted {
  src: string;
  /** box in fractions of the page (x, y top-left) */
  x: number;
  y: number;
  w: number;
  h: number;
  tilt?: number;
  position?: string;
  /** the typed label under the print */
  label?: string;
}

/** A 19th-century album page: card stock with a ruled border, prints with photo corners, typed labels in ink. */
export const AlbumPage: React.FC<{ items: Mounted[]; title?: string; children?: React.ReactNode }> = ({ items, title, children }) => {
  const { width: W, height: H } = useVideoConfig();
  const k = W / 1080;
  return (
    <AbsoluteFill style={{ background: ARCHIVE.paper, backgroundImage: 'radial-gradient(ellipse 80% 70% at 45% 40%, rgba(255,250,235,0.6), rgba(150,120,70,0.25))' }}>
      {/* ruled border */}
      <div style={{ position: 'absolute', left: 0.045 * W, top: 0.03 * H, right: 0.045 * W, bottom: 0.03 * H, border: `${2 * k}px solid rgba(70,50,25,0.55)`, outline: `${1 * k}px solid rgba(70,50,25,0.35)`, outlineOffset: `${6 * k}px` }} />
      {title && <div style={{ position: 'absolute', left: 0, width: W, top: 0.055 * H, textAlign: 'center', fontFamily: typewriter(700), fontWeight: 700, fontSize: 0.03 * W, letterSpacing: '0.3em', color: ARCHIVE.ink }}>{title}</div>}
      {items.map((m, i) => {
        const corner = 0.045 * W;
        const cornerStyle = (pos: React.CSSProperties, rot: number): React.CSSProperties => ({ position: 'absolute', width: corner, height: corner, background: '#1a1410', clipPath: 'polygon(0 0, 100% 0, 0 100%)', transform: `rotate(${rot}deg)`, ...pos });
        return (
          <div key={i} style={{ position: 'absolute', left: m.x * W, top: m.y * H, width: m.w * W, height: m.h * H, transform: `rotate(${m.tilt ?? 0}deg)` }}>
            <div style={{ position: 'absolute', inset: 0, background: '#d9cdb0', padding: 0.012 * W, boxSizing: 'border-box', boxShadow: `0 ${4 * k}px ${14 * k}px rgba(40,25,10,0.4)` }}>
              <Img src={m.src} style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: m.position ?? '50% 40%' }} />
            </div>
            <div style={cornerStyle({ left: -0.008 * W, top: -0.008 * W }, 0)} />
            <div style={cornerStyle({ right: -0.008 * W, top: -0.008 * W }, 90)} />
            <div style={cornerStyle({ right: -0.008 * W, bottom: -0.008 * W }, 180)} />
            <div style={cornerStyle({ left: -0.008 * W, bottom: -0.008 * W }, 270)} />
            {m.label && <div style={{ position: 'absolute', left: 0, width: '100%', top: '100%', marginTop: 0.018 * W, textAlign: 'center', fontFamily: typewriter(400), fontSize: 0.03 * W, color: ARCHIVE.ink, whiteSpace: 'pre' }}>{m.label}</div>}
          </div>
        );
      })}
      {children}
    </AbsoluteFill>
  );
};

// The photo treatment: every picture is printed as the process it was made with (PROCESS in tokens.ts): its tones
// mapped from a shadow colour to a highlight colour through levels and a soft S-curve, then film grain. The grain is
// a hash of the pixel and the frame step, so it boils on twos with the rest of the film, mono, strongest in the
// mid-tones (where real grain shows), sized about 1.5 px at 1080 wide.
import React from 'react';
import { Layer, shader } from '@kinetographdev/core';
import { AbsoluteFill, Img, useCurrentFrame, useVideoConfig } from 'remotion';
import { PROCESS, type Process } from './tokens.js';

const lin = (c: number) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
const linRgb = (hex: string) => { const n = parseInt(hex.replace('#', ''), 16); return [lin(((n >> 16) & 255) / 255), lin(((n >> 8) & 255) / 255), lin((n & 255) / 255)] as const; };

const TONE = /* wgsl */ `
fn hash(p: vec2<f32>) -> f32 {
  let q = fract(p * vec2<f32>(0.1031, 0.1030));
  let r = q + dot(q, q.yx + 33.33);
  return fract((r.x + r.y) * r.x);
}
fn toLin(c: f32) -> f32 { return select(pow((c + 0.055) / 1.055, 2.4), c / 12.92, c <= 0.04045); }

fn effect(px: vec2<f32>) -> vec4<f32> {
  let c = layer(px);
  if (c.a < 0.001) { return c; }
  let rgb = c.rgb / c.a;
  // tone in display terms
  var l = pow(max(dot(rgb, vec3<f32>(0.2126, 0.7152, 0.0722)), 0.0), 1.0 / 2.2);
  l = clamp((l - u.lo) / max(u.hi - u.lo, 0.01), 0.0, 1.0);
  l = pow(l, u.gamma);
  // a soft S-curve, as a print's paper and chemistry give
  l = mix(l, l * l * (3.0 - 2.0 * l), u.curve);
  // grain: two octaves of hashed noise on a cell of u.cell px, a new pattern each frame step
  let cell = max(u.cell, 0.5);
  let g1 = hash(floor(px / cell) + vec2<f32>(u.seed * 17.0, u.seed * 31.0)) - 0.5;
  let g2 = hash(floor(px / (cell * 2.0)) + vec2<f32>(u.seed * 7.0, 3.0)) - 0.5;
  let mid = 1.0 - abs(l * 2.0 - 1.0);
  l = clamp(l + (g1 * 0.7 + g2 * 0.5) * u.grain * (0.35 + 0.65 * mid), 0.0, 1.0);
  // fade: lift the blacks and lower the whites a little, an old print
  l = mix(u.fade, 1.0 - u.fade * 0.4, l);
  // map to the process colours, mixed in display space then back to linear
  let d = vec3<f32>(u.dr, u.dg, u.db);
  let w = vec3<f32>(u.lr, u.lg, u.lb);
  let toned = mix(d, w, l);
  let outc = vec3<f32>(toLin(toned.r), toLin(toned.g), toLin(toned.b));
  return vec4<f32>(outc * c.a, c.a);
}
`;

const disp = (hex: string) => { const n = parseInt(hex.replace('#', ''), 16); return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255] as const; };

export interface ToneProps {
  /** which process to print as (default albumen) */
  process?: Process;
  /** override the grain amount (0..0.2) and its cell in px at 1080 wide */
  grain?: number;
  cell?: number;
  /** S-curve 0..1, fade (lifted blacks) 0..0.15 */
  curve?: number;
  fade?: number;
  /** frames per grain pattern (2: on twos) */
  hold?: number;
}

/** The tone-and-grain effect for a layer. `frame` picks the grain pattern. */
export const toneEffect = ({ process = 'albumen', grain, cell = 1.6, curve = 0.35, fade = 0.04, hold = 2 }: ToneProps, W: number, frame: number) => {
  const p = PROCESS[process];
  const [dr, dg, db] = disp(p.dark), [lr, lg, lb] = disp(p.light);
  return shader({ code: TONE, uniforms: { dr, dg, db, lr, lg, lb, lo: p.lo, hi: p.hi, gamma: p.gamma, curve, fade, grain: grain ?? p.grain, cell: (cell * W) / 1080, seed: Math.floor(frame / hold) % 97 } });
};

/** Prints whatever is inside (a photo, a parallax stack) as the process. Full frame: move the content inside it. */
export const Toned: React.FC<ToneProps & { id: string; children: React.ReactNode }> = ({ id, children, ...p }) => {
  const f = useCurrentFrame();
  const { width: W } = useVideoConfig();
  return (
    <Layer id={id} effects={[toneEffect(p, W, f)]}>
      <AbsoluteFill>{children}</AbsoluteFill>
    </Layer>
  );
};

/** A photo filling the frame (cover), printed as the process. */
export const ArchivePhoto: React.FC<ToneProps & { id: string; src: string; position?: string; zoom?: number; origin?: string }> = ({ id, src, position = '50% 50%', zoom = 1, origin, ...p }) => (
  <Toned id={id} {...p}>
    <AbsoluteFill style={{ overflow: 'hidden' }}>
      <Img src={src} style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: position, transform: zoom !== 1 ? `scale(${zoom.toFixed(4)})` : undefined, transformOrigin: origin ?? position }} />
    </AbsoluteFill>
  </Toned>
);

export { linRgb };

// Graph Paper: the faint squared grid that sits behind so many explainer reels, under cut-out objects and big type: thin
// grey lines (or dots, or plus marks at the crossings) on an off-white ground, strongest round a focus and fading out
// towards the edges, with a soft light and a slow drift of the grid so the frame is never quite still. The drift moves
// a whole number of cells a loop, so it loops without a seam.
//
// Principles: restraint (lines at half strength, one ink, no motion above a cell in ten seconds), staging (the fade
// pulls the eye to the focus, where the subject goes), slow in and out (the drift is linear, the light is a slow sine),
// texture on the whole frame (grain on the root layer).

import React from 'react';
import { z } from 'zod';
import { GlslShader, Layer, grain } from '@kinetographdev/core';
import { useCurrentFrame, useVideoConfig } from 'remotion';
import { phase, rgb } from './lib.js';

export const DURATION = 300;

const hex = z.string().describe('A CSS colour.');

export const graphPaperSchema = z.object({
  ground: hex.describe('Paper colour.'),
  ink: hex.describe('Colour of the grid.'),
  kind: z.enum(['lines', 'dots', 'crosses']).describe('Ruled lines, a dot at each crossing, or a plus mark at each crossing.'),
  cell: z.number().min(12).max(200).describe('Grid cell, in pixels.'),
  line: z.number().min(0.5).max(4).describe('Line width (or dot radius), in pixels.'),
  major: z.number().int().min(0).max(10).describe('A stronger line every this many cells; 0 for none.'),
  strength: z.number().min(0).max(1).describe('How dark the grid is over the paper.'),
  focusX: z.number().min(0).max(1).describe('Where the grid is strongest, across (0 left, 1 right).'),
  focusY: z.number().min(0).max(1).describe('Where the grid is strongest, down (0 top, 1 bottom).'),
  fade: z.number().min(0.2).max(2).describe('How far from the focus the grid has faded out, as a fraction of the frame height. 2 for no fade.'),
  drift: z.enum(['none', 'up', 'left', 'diagonal']).describe('Which way the grid slides.'),
  speed: z.number().int().min(0).max(4).describe('Cells the grid slides per loop. Whole numbers, so it loops.'),
  light: z.number().min(0).max(0.4).describe('How much the corners darken round a soft light.'),
  grain: z.number().min(0).max(0.3).describe('Grain amount over the whole frame.'),
});
export type GraphPaperProps = z.infer<typeof graphPaperSchema>;

export const graphPaperDefaults: GraphPaperProps = {
  ground: '#f3f2ee',
  ink: '#a9a8a3',
  kind: 'lines',
  cell: 56,
  line: 1.2,
  major: 0,
  strength: 0.5,
  focusX: 0.5,
  focusY: 0.45,
  fade: 0.85,
  drift: 'diagonal',
  speed: 1,
  light: 0.12,
  grain: 0.04,
};

const FRAGMENT = `
precision highp float;
uniform vec2 u_res; uniform vec2 u_off;
uniform float u_cell; uniform float u_line; uniform float u_major; uniform float u_kind;
uniform vec3 u_bg; uniform vec3 u_ink; uniform float u_str;
uniform vec2 u_focus; uniform float u_fade; uniform float u_light; uniform float u_ph;

// distance in px from p to the nearest grid line, on each axis
vec2 toLine(vec2 p, float cell){ return abs(fract(p / cell - 0.5) - 0.5) * cell; }

void main(){
  vec2 px = gl_FragCoord.xy;
  vec2 p = px + u_off;
  float aa = 0.8;
  float lw = u_line * 0.5;
  vec2 f = toLine(p, u_cell);
  float cov = 0.0;
  if (u_kind < 0.5) {
    cov = smoothstep(lw + aa, lw - aa, min(f.x, f.y));
    if (u_major > 0.5) {
      vec2 fm = toLine(p, u_cell * u_major);
      float m = smoothstep(lw * 1.8 + aa, lw * 1.8 - aa, min(fm.x, fm.y));
      cov = max(cov * 0.6, m);
    }
  } else if (u_kind < 1.5) {
    float r = u_line * 1.3;
    cov = smoothstep(r + aa, r - aa, length(f));
  } else {
    float arm = u_cell * 0.11;
    float h = smoothstep(lw + aa, lw - aa, f.y) * smoothstep(arm + aa, arm - aa, f.x);
    float v = smoothstep(lw + aa, lw - aa, f.x) * smoothstep(arm + aa, arm - aa, f.y);
    cov = max(h, v);
  }
  // strongest round the focus, gone by u_fade frame-heights away
  vec2 q = (px - u_focus * u_res) / u_res.y;
  float keep = u_fade >= 1.99 ? 1.0 : 1.0 - smoothstep(u_fade * 0.3, u_fade, length(q));
  // a soft light that breathes a little round the focus
  vec2 l = (px - (u_focus + vec2(0.03 * cos(u_ph), 0.02 * sin(u_ph))) * u_res) / u_res.y;
  vec3 bg = u_bg * (1.0 - u_light * smoothstep(0.25, 1.3, length(l)));
  gl_FragColor = vec4(mix(bg, u_ink, cov * u_str * keep), 1.0);
}
`;

/** Faint graph paper on an off-white ground, fading out from a focus, sliding slowly. `id` prefixes its layer ids, for
 *  two papers on screen at once (a camera pan between scenes). */
export const GraphPaper: React.FC<GraphPaperProps & { id?: string }> = (p) => {
  const frame = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const ph = phase(frame, DURATION, 1);
  const slide = ((frame % DURATION) / DURATION) * p.speed * p.cell;
  // gl_FragCoord runs up, so "up" on screen adds to y
  const dir = p.drift === 'up' ? [0, -1] : p.drift === 'left' ? [1, 0] : p.drift === 'diagonal' ? [1, -1] : [0, 0];
  return (
    <Layer id={`${p.id ?? 'gp'}-root`} effects={p.grain > 0 ? [grain(p.grain, { seed: 11, size: 1.2 })] : undefined}>
      <GlslShader
        id={`${p.id ?? 'gp'}-shader`}
        width={W}
        height={H}
        fragment={FRAGMENT}
        uniforms={{
          u_res: [W, H], u_off: [dir[0]! * slide, dir[1]! * slide], u_cell: p.cell, u_line: p.line, u_major: p.major,
          u_kind: p.kind === 'lines' ? 0 : p.kind === 'dots' ? 1 : 2, u_bg: rgb(p.ground), u_ink: rgb(p.ink), u_str: p.strength,
          u_focus: [p.focusX, 1 - p.focusY], u_fade: p.fade, u_light: p.light, u_ph: ph,
        }}
      />
    </Layer>
  );
};

// Shared bits for the backgrounds: colour parsing for shader uniforms, the loop phase, and the GLSL noise every shader uses.

/** "#rrggbb" or "#rgb" to [r, g, b] in 0..1 for a vec3 uniform. */
export const rgb = (hex: string): [number, number, number] => {
  let h = hex.replace('#', '');
  if (h.length === 3) h = h.split('').map((c) => c + c).join('');
  const n = parseInt(h.slice(0, 6), 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
};

/** Phase in radians that completes a whole turn over `loop` frames, scaled by speed. A whole number of turns per loop
 *  (speed 1, 2, 3 ...) makes the clip loop without a seam; other speeds drift without looping. */
export const phase = (frame: number, loop: number, speed: number) => (2 * Math.PI * frame * speed) / loop;

export const NOISE_GLSL = `
float hash(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }
float vnoise(vec2 p){
  vec2 i=floor(p); vec2 f=fract(p); f=f*f*(3.0-2.0*f);
  float a=hash(i); float b=hash(i+vec2(1.0,0.0)); float c=hash(i+vec2(0.0,1.0)); float d=hash(i+vec2(1.0,1.0));
  return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);
}
float fbm(vec2 p){
  float v=0.0; float a=0.5;
  for(int i=0;i<5;i++){ v+=a*vnoise(p); p=p*2.02+17.1; a*=0.5; }
  return v;
}
`;

// Cutting the curve: two shots under one parent transform whose scale runs on an After Effects
// "speed spike" ease, speed 0 at both keys with influence dragged to about 97%: cubic-bezier(0.97, 0, 0.03, 1). The
// cut sits on the middle frame, where the move is fastest, so the eye reads one continuous move across two pictures.
// Measured: at the seamless cut the zoom-out runs -3.6% a frame before and -2.1% after (one continuous decay); the
// matched shape (a pediment apex) keeps its x within 4 px across the cut, its size need not match. Both shots are on
// twos in the reference (wrap in <Posterize>).
import React from 'react';
import { AbsoluteFill, Easing, interpolate, useCurrentFrame } from 'remotion';

export const SPEED_SPIKE = Easing.bezier(0.97, 0, 0.03, 1);

export interface CurveCutProps {
  /** the shot before the cut and the one after */
  a: React.ReactNode;
  b: React.ReactNode;
  /** the move's first frame and length; the cut is at its middle frame unless `cut` says otherwise */
  start: number;
  duration: number;
  cut?: number;
  /** scale at the two keys (2.2 -> 1 zooms out, 1 -> 2.2 pushes in) */
  scale?: [number, number];
  /** a slide too, in fractions of the frame, at the two keys */
  shift?: [[number, number], [number, number]];
  /** the pivot, fractions of the frame: put it on the shape the two shots share */
  pivot?: [number, number];
}

export const CurveCut: React.FC<CurveCutProps> = ({ a, b, start, duration, cut, scale = [2.2, 1], shift = [[0, 0], [0, 0]], pivot = [0.5, 0.5] }) => {
  const f = useCurrentFrame();
  const t = interpolate(f, [start, start + duration], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: SPEED_SPIKE });
  const s = scale[0] + (scale[1] - scale[0]) * t;
  const dx = shift[0][0] + (shift[1][0] - shift[0][0]) * t, dy = shift[0][1] + (shift[1][1] - shift[0][1]) * t;
  const at = cut ?? start + Math.floor(duration / 2);
  return (
    <AbsoluteFill style={{ overflow: 'hidden' }}>
      <AbsoluteFill style={{ transform: `translate(${(dx * 100).toFixed(3)}%, ${(dy * 100).toFixed(3)}%) scale(${s.toFixed(4)})`, transformOrigin: `${pivot[0] * 100}% ${pivot[1] * 100}%` }}>
        {f < at ? a : b}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// Film finishing, measured off three reels:
//
//   GateWeave     Da3YpRipHuF: AE Transform with Position wiggle(12, 2). Measured: a new position every 2nd frame,
//                 each step independent, std about 1.1 px in x and 1.7 px in y at 1080 wide (peak about 4), no
//                 rotation or scale; the picture overscanned about 1.5% so its edge never shows.
//   Flicker       same reel: Exposure with wiggle(14, .2). Measured luma std 1.7% (about 0.024 stops), every frame,
//                 no hue shift.
//   Dust          DZFqNzwAqVa / DdKZ5oBpPCW: light specks and a few hairs, Screen only: about 240 specks per Mpx,
//                 median about 20 px in area, +35 to +60 luma at their core; a pattern holds 8 to 15 frames, then
//                 another; the stock plate also drifts (about 5 px a frame to the left).
//   WindowLight   DdKZ5oBpPCW: a greyscale window-light plate in Multiply, multiplying the lit sky by about 0.53 in its
//                 shadows, sliding slowly (+127 px over the clip) for "light gently drifting".
//   EdgeBlur      DZFqNzwAqVa: the "fringe blur" is not chromatic aberration (R, G, B shifts measured 0): it is a lens
//                 blur through a radial map: sharp in an ellipse about (0.5 W, 0.42 H), about 45-60 px at the top and
//                 bottom edges and 10-20 px at the sides.
//   Vignette      same reel: a multiply falloff centred near (0.45 W, 0.31 H): 0.73 at the top edge, 0.76-0.85 at the
//                 sides, 0.36-0.39 at the bottom edge and corners.
//   VoxFinish     the reel's whole stack, top to bottom: zoom (+9.4% over 44 frames), vignette, dust (screen), the
//                 edge blur, the picture.
import React from 'react';
import { AbsoluteFill, random, useCurrentFrame, useVideoConfig } from 'remotion';

/** A normal-ish random number (sum of three uniforms, scaled to std 1) for a seed. */
const gauss = (seed: string) => ((random(`${seed}a`) + random(`${seed}b`) + random(`${seed}c`)) - 1.5) / 0.5;

/** The picture jitters like film in a projector gate. `mode="reel"` (default) is what the reel measured: a new offset
 *  every `hold` frames, std 1.1 / 1.7 px. `mode="preset"` is the reference's GateWeave.ffx:
 *  Transform Position + random(-1.5, 1.5) px per axis, re-seeded floor(time * 24), Scale 101%. */
export const GateWeave: React.FC<{ amount?: number; hold?: number; seed?: string; overscan?: number; mode?: 'reel' | 'preset'; children: React.ReactNode }> = ({ amount = 1, hold = 2, seed = 'weave', overscan, mode = 'reel', children }) => {
  const f = useCurrentFrame();
  const { width: W, fps } = useVideoConfig();
  const k = (amount * W) / 1080;
  let x: number, y: number;
  if (mode === 'preset') {
    const step = Math.floor((f / fps) * 24);
    x = (random(`${seed}x${step}`) * 2 - 1) * 1.5 * k;
    y = (random(`${seed}y${step}`) * 2 - 1) * 1.5 * k;
  } else {
    const step = Math.floor(f / hold);
    x = gauss(`${seed}x${step}`) * 1.1 * k;
    y = gauss(`${seed}y${step}`) * 1.7 * k;
  }
  const s = overscan ?? (mode === 'preset' ? 1.01 : 1.015);
  return <AbsoluteFill style={{ transform: `translate(${x.toFixed(2)}px, ${y.toFixed(2)}px) scale(${s})` }}>{children}</AbsoluteFill>;
};

/** Exposure flicker: brightness 2^(stops), a new value every frame. Default: std `stops` (0.024 measured off the reel;
 *  the reference's presets use random(-S, S) with S 0.02-0.04). `heavy` is HeavyFlicker.ffx: Exposure wiggle(24, .2),
 *  about ±0.2 stops. */
export const Flicker: React.FC<{ stops?: number; heavy?: boolean; seed?: string; children: React.ReactNode }> = ({ stops = 0.024, heavy = false, seed = 'flicker', children }) => {
  const f = useCurrentFrame();
  const e = heavy ? (random(`${seed}h${f}`) * 2 - 1) * 0.2 : gauss(`${seed}${f}`) * stops;
  const b = 2 ** e;
  return <AbsoluteFill style={{ filter: `brightness(${b.toFixed(4)})` }}>{children}</AbsoluteFill>;
};

/** Film dust: light specks and hairs, screened over everything; a pattern holds 8 to 15 frames, then another. */
export const Dust: React.FC<{ density?: number; strength?: number; drift?: number; hairs?: number; seed?: string }> = ({ density = 240, strength = 0.5, drift = 0, hairs = 2, seed = 'dust' }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  // which pattern is up: patterns of 8-15 frames laid end to end
  let start = 0, n = 0;
  while (true) { const len = 8 + Math.floor(random(`${seed}len${n}`) * 8); if (start + len > f) break; start += len; n++; }
  const count = Math.round((density * W * H) / 1e6);
  const dx = -drift * f;
  const specks = Array.from({ length: count }, (_, i) => {
    const s = `${seed}${n}s${i}`;
    const r = Math.max(0.6, (1.2 + 2.2 * random(`${s}r`) ** 3) * (W / 1080));
    return { x: (((random(`${s}x`) * W + dx) % W) + W) % W, y: random(`${s}y`) * H, r, a: 0.35 + 0.65 * random(`${s}a`) };
  });
  const lines = Array.from({ length: hairs }, (_, i) => {
    const s = `${seed}${n}h${i}`;
    if (random(`${s}on`) < 0.45) return null;
    const x = random(`${s}x`) * W, y = random(`${s}y`) * H, len = (40 + 120 * random(`${s}l`)) * (W / 1080), a = random(`${s}t`) * Math.PI;
    const c = Math.cos(a) * len, d = Math.sin(a) * len, bend = (random(`${s}b`) - 0.5) * len;
    return `M${x} ${y} q${(c / 2 - d * bend / len).toFixed(1)} ${(d / 2 + c * bend / len).toFixed(1)} ${c.toFixed(1)} ${d.toFixed(1)}`;
  }).filter(Boolean) as string[];
  return (
    <svg width={W} height={H} style={{ position: 'absolute', left: 0, top: 0, mixBlendMode: 'screen', opacity: strength, pointerEvents: 'none' }}>
      <g style={{ filter: `blur(${(0.6 * W / 1080).toFixed(2)}px)` }}>
        {specks.map((p, i) => <circle key={i} cx={p.x} cy={p.y} r={p.r} fill={`rgba(255,255,255,${p.a.toFixed(2)})`} />)}
        {lines.map((d, i) => <path key={`h${i}`} d={d} stroke="rgba(255,255,255,0.8)" strokeWidth={1.2 * (W / 1080)} fill="none" />)}
      </g>
    </svg>
  );
};

/** Window light falling across the picture, multiplied: soft slanted bars and leaf shadows, drifting slowly. */
export const WindowLight: React.FC<{ strength?: number; drift?: number; angle?: number }> = ({ strength = 0.47, drift = 0.12, angle = -24 }) => {
  const f = useCurrentFrame();
  const { width: W, height: H, durationInFrames } = useVideoConfig();
  const x = (drift * W * f) / Math.max(1, durationInFrames);
  const k = W / 1080;
  return (
    <AbsoluteFill style={{ mixBlendMode: 'multiply', pointerEvents: 'none', opacity: strength }}>
      <svg width={W * 1.6} height={H * 1.4} style={{ position: 'absolute', left: -0.3 * W + x, top: -0.2 * H, filter: `blur(${(26 * k).toFixed(0)}px)` }}>
        <g transform={`rotate(${angle} ${W * 0.8} ${H * 0.7})`}>
          {/* the window: two panes of light with a mullion and a transom between, the rest of the wall in shadow */}
          <rect x={0} y={0} width={W * 1.6} height={H * 1.4} fill="#000" />
          <rect x={W * 0.25} y={H * 0.12} width={W * 0.42} height={H * 0.5} fill="#fff" />
          <rect x={W * 0.73} y={H * 0.12} width={W * 0.42} height={H * 0.5} fill="#fff" />
          <rect x={W * 0.25} y={H * 0.66} width={W * 0.42} height={H * 0.45} fill="#fff" />
          <rect x={W * 0.73} y={H * 0.66} width={W * 0.42} height={H * 0.45} fill="#fff" />
          {/* leaves outside, breaking up the light */}
          {Array.from({ length: 9 }, (_, i) => <ellipse key={i} cx={W * (0.3 + 0.9 * random(`leaf${i}x`))} cy={H * (0.15 + 0.9 * random(`leaf${i}y`))} rx={W * (0.04 + 0.06 * random(`leaf${i}r`))} ry={W * 0.03} fill="#000" opacity={0.6} transform={`rotate(${random(`leaf${i}a`) * 180})`} />)}
        </g>
      </svg>
    </AbsoluteFill>
  );
};

/** (A picture holding a <Layer> with an id must be made twice with two ids: one for under, one for here.)
 *  The radial lens blur: a blurred copy of the picture shows through a mask that is clear in a central ellipse and
 *  solid at the edges, strongest top and bottom. Pass the same picture you draw underneath: the copy must line up with
 *  it exactly (no scale), and where its blur thins at the frame edge the sharp picture shows instead. */
export const EdgeBlur: React.FC<{ radius?: number; cx?: number; cy?: number; children: React.ReactNode }> = ({ radius = 45, cx = 0.5, cy = 0.42, children }) => {
  const { width: W } = useVideoConfig();
  const mask = `radial-gradient(ellipse 62% 40% at ${cx * 100}% ${cy * 100}%, transparent 45%, rgba(0,0,0,0.55) 75%, #000 100%)`;
  return (
    <AbsoluteFill style={{ WebkitMaskImage: mask, maskImage: mask, pointerEvents: 'none' }}>
      <AbsoluteFill style={{ filter: `blur(${((radius * W) / 1080).toFixed(1)}px)`, }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

/** The measured vignette, multiplied: lighter at the top, twice as dark at the bottom corners (an SVG radial
 *  gradient, so its shape is exact). */
export const Vignette: React.FC<{ strength?: number; cx?: number; cy?: number }> = ({ strength = 1, cx = 0.45, cy = 0.31 }) => {
  const { width: W, height: H } = useVideoConfig();
  // the farthest corner from the centre sets the radius; stops measured: 0.73 at the top edge, 0.8 at the sides,
  // 0.37 at the bottom corners (multiply factors, so black at 1 - factor)
  const r = Math.hypot(Math.max(cx, 1 - cx) * W, Math.max(cy, 1 - cy) * H);
  return (
    <svg width={W} height={H} style={{ position: 'absolute', left: 0, top: 0, pointerEvents: 'none', opacity: strength }}>
      <defs>
        <radialGradient id="kg-vignette" gradientUnits="userSpaceOnUse" cx={cx * W} cy={cy * H} r={r} gradientTransform={`translate(${cx * W} ${cy * H}) scale(0.78 1) translate(${-cx * W} ${-cy * H})`}>
          <stop offset="0.3" stopColor="#000" stopOpacity={0} />
          <stop offset="0.5" stopColor="#000" stopOpacity={0.2} />
          <stop offset="0.75" stopColor="#000" stopOpacity={0.45} />
          <stop offset="1" stopColor="#000" stopOpacity={0.64} />
        </radialGradient>
      </defs>
      <rect width={W} height={H} fill="url(#kg-vignette)" />
    </svg>
  );
};

/** The Vox finish over a picture: a slow push, edge blur, dust and vignette, with optional weave and flicker. */
export const VoxFinish: React.FC<{ picture: React.ReactNode; push?: number; weave?: boolean; flicker?: boolean; dust?: number; blur?: number; vignette?: number }> = ({ picture, push = 0.0021, weave = true, flicker = true, dust = 0.55, blur = 45, vignette = 1 }) => {
  const f = useCurrentFrame();
  let body = (
    <AbsoluteFill style={{ transform: `scale(${(1 + push * f).toFixed(4)})` }}>
      {picture}
      {blur > 0 && <EdgeBlur radius={blur}>{picture}</EdgeBlur>}
    </AbsoluteFill>
  );
  if (weave) body = <GateWeave>{body}</GateWeave>;
  if (flicker) body = <Flicker>{body}</Flicker>;
  return (
    <AbsoluteFill style={{ overflow: 'hidden', background: '#000' }}>
      {body}
      {dust > 0 && <Dust strength={dust} />}
      {vignette > 0 && <Vignette strength={vignette} />}
    </AbsoluteFill>
  );
};

// Looks: finishing and editing techniques read off reference reels,
// each measured and built for Kinetograph. Any reel or taste can use them.
export { Posterize } from './posterize.js';
export { CurveCut, SPEED_SPIKE } from './curve-cut.js';
export type { CurveCutProps } from './curve-cut.js';
export { Parallax } from './parallax.js';
export type { ParallaxLayer, ParallaxProps } from './parallax.js';
export { PageTurn } from './page-turn.js';
export type { PageTurnProps } from './page-turn.js';
export { Dust, EdgeBlur, Flicker, GateWeave, Vignette, VoxFinish, WindowLight } from './film.js';

// CC Page Turn, as a WGSL shader on the turning page. The reference's panel: Controls = Bottom
// Right Corner, Fold Radius 50, Light Direction -60 deg, Render = Front & Back Page with the layer itself as the back
// (so the back is the mirrored front), Back Opacity 85 over a light paper colour. Measured on the turn: about 12
// frames of slow lift off the corner, then a constant sweep of about 44 px a frame at 1080 wide, the fold line
// tilting from 8.6 to 23 degrees as the fold position runs from corner to corner; no hard crease, soft shading
// across the bend; on the revealed page a shadow beside the fold, -15% at the edge, gone in about 100 px. The page
// that turns sits above the page it reveals.
//
// The geometry is a cylinder of radius R lying on the fold line. Along the fold normal, page material up to the line
// stays flat; the next pi R of it wraps over the cylinder; the rest lies flat on top, upside down, coming back over
// the page. Each output pixel takes the topmost of those that covers it: the flat back, the back of the cylinder, the
// front of the cylinder, the flat front; where none does, the page below shows through, shaded by the curl's shadow.
import React from 'react';
import { Layer, shader, useCurrentFrame, useVideoConfig } from '@kinetographdev/core';
import { AbsoluteFill, interpolate } from 'remotion';

const CURL = /* wgsl */ `
const PI: f32 = 3.14159265;

fn inPage(p: vec2<f32>) -> bool {
  return p.x >= 0.0 && p.y >= 0.0 && p.x <= globals.canvas.x && p.y <= globals.canvas.y;
}

fn effect(px: vec2<f32>) -> vec4<f32> {
  let corner = vec2<f32>(u.cx, u.cy);
  let fold = vec2<f32>(u.fx, u.fy);
  let span = corner - fold;
  if (length(span) < 0.5) { return layer(px); }
  // n points from the fold line toward the corner; the line passes through the middle of corner and fold point
  let n = normalize(span);
  let mid = (corner + fold) * 0.5;
  let r = max(u.radius, 1.0);
  let x = dot(px - mid, n);
  let paper = vec4<f32>(u.pr, u.pg, u.pb, 1.0);
  // light from the panel's direction, as a 2D vector on the page
  let light = vec2<f32>(cos(u.light), sin(u.light));
  let lit = 0.5 + 0.5 * dot(n, light);

  // 1. the flat back, upside down on top: material m = pi r - x, for x <= 0
  if (x <= 0.0) {
    let m = PI * r - x;
    let src = px + n * (m - x);
    if (inPage(src)) {
      let c = layer(src);
      if (c.a > 0.01) {
        let back = mix(paper, c, u.back);
        return vec4<f32>(back.rgb * (0.86 + 0.1 * lit), 1.0);
      }
    }
  }
  if (x >= 0.0 && x <= r) {
    // 2. the back of the cylinder (angle past 90 degrees), seen from above
    let phiB = PI - asin(x / r);
    let srcB = px + n * (r * phiB - x);
    if (inPage(srcB)) {
      let c = layer(srcB);
      if (c.a > 0.01) {
        let back = mix(paper, c, u.back);
        let shade = 0.72 + 0.26 * sin(phiB) * lit + 0.1 * (1.0 - sin(phiB));
        return vec4<f32>(back.rgb * shade, 1.0);
      }
    }
    // 3. the front of the cylinder (angle up to 90 degrees), curving up away from the page
    let phiF = asin(x / r);
    let srcF = px + n * (r * phiF - x);
    if (inPage(srcF)) {
      let c = layer(srcF);
      if (c.a > 0.01) {
        let shade = 1.0 - 0.38 * (1.0 - cos(phiF)) * (1.1 - 0.4 * lit);
        return vec4<f32>(c.rgb * shade, c.a);
      }
    }
  }
  // 4. the flat front, before the fold
  if (x < 0.0) {
    return layer(px);
  }
  // 5. nothing of this page here: the page below shows, under the curl's shadow (strongest at the cylinder's edge)
  let d = max(0.0, x - r * 0.6);
  let a = u.shadow * (1.0 - smoothstep(0.0, u.shadowWidth, d));
  return vec4<f32>(0.0, 0.0, 0.0, a);
}
`;

const lin = (c: number) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
const hexLinear = (hex: string) => { const n = parseInt(hex.replace('#', ''), 16); return [lin(((n >> 16) & 255) / 255), lin(((n >> 8) & 255) / 255), lin((n & 255) / 255)]; };

export interface PageTurnProps {
  /** a unique layer id */
  id: string;
  /** the page that turns (drawn full frame) and the page it reveals */
  page: React.ReactNode;
  under?: React.ReactNode;
  /** the turn's first frame and length */
  start: number;
  duration: number;
  /** the corner that lifts */
  corner?: 'bottom-right' | 'bottom-left' | 'top-right' | 'top-left';
  /** Fold Radius in px at 1080 wide (the reference's 50) */
  radius?: number;
  /** Light Direction in degrees (-60) */
  light?: number;
  /** Back Opacity, 0..1 (0.85), and the paper the back is printed on */
  back?: number;
  paper?: string;
  /** the shadow on the revealed page: strength at the fold (0.15) and how far it reaches in px at 1080 (100) */
  shadow?: number;
  shadowWidth?: number;
  /** turn the page in (it lands) instead of out */
  reverse?: boolean;
}

/** Where the dragged corner is, 0..1 of the turn: a slow lift for the first 40%, then a constant sweep. */
const travel = (t: number) => (t < 0.4 ? 0.12 * (t / 0.4) ** 2 : 0.12 + 0.88 * ((t - 0.4) / 0.6));

export const PageTurn: React.FC<PageTurnProps> = ({ id, page, under, start, duration, corner = 'bottom-right', radius = 50, light = -60, back = 0.85, paper = '#d8d6d0', shadow = 0.15, shadowWidth = 100, reverse }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  let t = interpolate(f, [start, start + duration], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  if (reverse) t = 1 - t;
  const k = travel(t);
  const right = corner.endsWith('right'), bottom = corner.startsWith('bottom');
  const cx = right ? W : 0, cy = bottom ? H : 0;
  // the fold position runs from the corner past the opposite corner, so the page leaves the frame completely; the
  // vertical part lags the horizontal, which tilts the fold line as it travels (8.6 to 23 degrees in the reference)
  const ox = right ? -1.15 * W : 2.15 * W, oy = bottom ? -0.35 * H : 1.35 * H;
  const fx = cx + (ox - cx) * k, fy = cy + (oy - cy) * k * k;
  const [pr, pg, pb] = hexLinear(paper);
  const s = W / 1080;
  return (
    <AbsoluteFill>
      {under}
      {k < 0.999 && (
        <Layer id={id} effects={[shader({ code: CURL, uniforms: { cx, cy, fx, fy, radius: radius * s, light: (light * Math.PI) / 180, back, pr: pr!, pg: pg!, pb: pb!, shadow, shadowWidth: shadowWidth * s } })]}>
          <AbsoluteFill>{page}</AbsoluteFill>
        </Layer>
      )}
    </AbsoluteFill>
  );
};

// Parallax from one photo cut into layers: foreground, midground and background cut-outs (the
// hole behind a cut-out filled), spaced in depth so a sideways camera slide moves them at different speeds. Measured:
// the plugin's 50 mm camera with layers 1000 apart gives shift factors 3.0 : 1.0 : 0.6 (foreground 382 px against
// background 78 px over the same 80 frames), no scale change, the foreground out of focus, all on twos.
import React from 'react';
import { AbsoluteFill, Easing, Img, interpolate, useCurrentFrame, useVideoConfig } from 'remotion';

export interface ParallaxLayer {
  /** a picture (a cut-out PNG for all but the back) or any node */
  src?: string;
  node?: React.ReactNode;
  /** how far it moves for one unit of camera travel: 3 for the foreground, 1 for the subject, 0.6 for the background */
  factor: number;
  /** defocus in px at 1080 wide (the foreground's) */
  blur?: number;
  /** its own extra drift over the move, fractions of W, e.g. a cable car travelling the other way */
  drift?: number;
}

export interface ParallaxProps {
  /** back to front */
  layers: ParallaxLayer[];
  start: number;
  duration: number;
  /** camera travel for factor 1, fractions of W (negative: the picture moves left) */
  travel?: number;
  /** vertical travel for factor 1, fractions of H */
  rise?: number;
}

export const Parallax: React.FC<ParallaxProps> = ({ layers, start, duration, travel = -0.07, rise = 0 }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const t = interpolate(f, [start, start + duration], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.cubic) });
  return (
    <AbsoluteFill style={{ overflow: 'hidden' }}>
      {layers.map((ly, i) => {
        const k = ly.factor, x = (travel * k + (ly.drift ?? 0)) * t * W, y = rise * k * t * H;
        // drawn large enough that its edge never enters the frame over the whole move
        const grow = 1 + 2 * Math.max(Math.abs(travel * k), Math.abs(rise * k));
        return (
          <AbsoluteFill key={i} style={{ transform: `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) scale(${grow.toFixed(3)})`, filter: ly.blur ? `blur(${((ly.blur * W) / 1080).toFixed(1)}px)` : undefined }}>
            {ly.node ?? (ly.src && <Img src={ly.src} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />)}
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

// Posterize Time: hold every frame for `step` frames, so motion steps like animation on twos (12 fps at 24) or threes
// (8 fps). Measured on the references: the curve-cut and parallax reels run on twos, the posterized page turns on
// threes; nothing is motion blurred, each held pose is crisp. Wrap anything; audio inside is silent (as in a Freeze).
import React from 'react';
import { Freeze, useCurrentFrame } from 'remotion';

/** Children see only every `step`th frame (default 2: on twos). `offset` shifts which frames are held. */
export const Posterize: React.FC<{ step?: number; offset?: number; children: React.ReactNode }> = ({ step = 2, offset = 0, children }) => {
  const f = useCurrentFrame();
  if (step <= 1) return <>{children}</>;
  return <Freeze frame={Math.max(0, Math.floor((f - offset) / step) * step + offset)}>{children}</Freeze>;
};

// The explainer's frame and motion. The numbers are each taste's (taste.ts); the defaults and the notes below are BASE,
// measured off pin 1119 read frame by frame at 30 fps, unless marked otherwise:
//
//   entrance   objects arrive on an exponential ease-out: each frame they cover the same share of the distance left
//              (0.12 for a rise from the bottom, 0.18 for a slide from the right), no overshoot, no blur
//   push       a beat can leave by sliding left in layers, each on a quadratic ease-in of its own speed, so the lead goes
//              first and fastest, the keyword next, the object last: a parallax push (`push`)
//   dissolve   a line can leave by a wave running left to right at 0.046 W a frame, each letter fading and blurring as
//              it passes (`wave`)
//   cut        otherwise beats cut hard; the paper does not move between them
//   circle     one designed wipe: a hard-edged black disc growing from the object's centre, 0.115 W of radius a frame
//   stars      black four-point corner stars with needle arms grow in over 6-7 frames (0.75 of the length still to
//              grow left each frame), then breathe +-10% slowly; on dark beats they are blurred and dark red, still
//
// Shadows follow one light, top right: a star's falls down-left off its concave edges, as an object's does (props.tsx).

import React from 'react';
import { AbsoluteFill, staticFile, useCurrentFrame, useVideoConfig } from 'remotion';
import { GraphPaper, graphPaperDefaults } from '../../components/backgrounds/graph-paper.js';
import type { CornerKind, ExplainerTaste, WipeKind } from './taste.js';

export const clamp01 = (t: number) => Math.min(1, Math.max(0, t));
/** 0..1 over `dur` frames from `at`. */
export const prog = (f: number, at: number, dur: number) => clamp01((f - at) / Math.max(1, dur));

/** The exponential ease-out of every entrance: `from` before `t0`, then `keep` of the remaining distance left each frame
 *  (0.88 for a rise, 0.82-0.89 for a slide). */
export const expo = (f: number, t0: number, from: number, to: number, keep: number) => (f < t0 ? from : to + (from - to) * keep ** (f - t0));

/** A layer's offset in a push exit: 0 before `t0`, then `-k (f - t0)^2` (in whatever unit `k` is, usually W). Measured k
 *  for the lead, keyword and object: 0.005, 0.0027, 0.010 W, starting on frames 0, +1 and +4 of the push. */
export const push = (f: number, t0: number, k: number) => (f < t0 ? 0 : -k * (f - t0) ** 2);

/** How far a dissolve wave starting at `t0` has gone with a letter at `x` (fraction of W): 0 untouched, 1 gone. The
 *  front moves `speed` W a frame from `x0` (0.046 measured), and a letter takes `fade` frames to fade once reached. */
export const wave = (f: number, t0: number | undefined, x: number, x0 = 0, speed = 0.046, fade = 3) =>
  (t0 === undefined ? 0 : clamp01((f - t0 - (x - x0) / speed) / fade));

const GraphPaperFor: React.FC<{ taste: ExplainerTaste; id?: string }> = ({ taste, id }) => {
  const { width: W } = useVideoConfig();
  return <GraphPaper {...graphPaperDefaults} id={id} ground={taste.paper} ink={taste.gridInk ?? '#b4b3ae'} strength={taste.gridStrength ?? 0.45}
    cell={Math.max(12, Math.min(200, (taste.gridCell ?? 64 / 1080) * W))} fade={0.95} focusY={0.4} speed={0} light={0} grain={0} />;
};

/** The paper: flat, as measured; a vignette and graph paper when the taste has them. Give each paper on screen at once
 *  its own `id` (two scenes in a pan). */
export const Paper: React.FC<{ taste: ExplainerTaste; dark?: boolean; id?: string }> = ({ taste, dark, id }) => (
  <AbsoluteFill style={{ background: dark ? taste.dark : taste.paper }}>
    {!dark && taste.grid && <GraphPaperFor taste={taste} id={id} />}
    {!dark && taste.vignette > 0 && <AbsoluteFill style={{ background: `radial-gradient(ellipse 75% 62% at 50% 45%, rgba(0,0,0,0) 40%, rgba(40,38,34,${taste.vignette}) 100%)` }} />}
  </AbsoluteFill>
);

// a four-point star with concave sides pulled almost to the centre, so its arms are needles; `l` is the arm length
const starPath = (l: number) => {
  const c = l * 0.045, d = l * 0.18;
  return `M${l} 0 C${d} ${c} ${c} ${d} 0 ${l} C${-c} ${d} ${-d} ${c} ${-l} 0 C${-d} ${-c} ${-c} ${-d} 0 ${-l} C${c} ${-d} ${d} ${-c} ${l} 0 Z`;
};

/** A corner shape's size on frame `f`: nothing before `t0`, grown in keeping `grow` of the length still to grow each
 *  frame (0.75 measured: 6-7 frames), then `breathe` (a fraction, signed) of drift over the next `span` frames. */
export const starLength = (f: number, t0: number, length: number, breathe = 0, span = 90, grow = 0.75) =>
  f < t0 ? 0 : length * (1 - grow ** (f - t0 + 1)) * (1 + breathe * clamp01((f - t0 - 6) / span));

/** `starLength` with the taste's growth; `breathe` is signed, as a share of the taste's own breathing. */
export const cornerLength = (taste: ExplainerTaste, f: number, t0: number, length: number, breathe = 1, span = 90) =>
  starLength(f, t0, length, breathe * taste.shapes.breathe, span, taste.shapes.grow);

/** One corner shape at arm length (or radius) `l` px, centred on 0,0. Filled shapes fill, line shapes stroke. */
const shapeEl = (kind: CornerKind, l: number, color: string, extra?: React.SVGProps<SVGPathElement>) => {
  const k = l * 0.18;
  switch (kind) {
    case 'needle': return <path d={starPath(l)} fill={color} {...extra} />;
    // a four-point sparkle: the same star with its sides pulled in less, so the arms are fat and soft
    case 'sparkle': return <path d={`M${l} 0 Q${k} ${k} 0 ${l} Q${-k} ${k} ${-l} 0 Q${-k} ${-k} 0 ${-l} Q${k} ${-k} ${l} 0 Z`} fill={color} {...extra} />;
    // six thin round-capped strokes through the centre, a drawn asterisk
    case 'asterisk': {
      const arms = [0, 60, 120].map((a) => { const r = (a * Math.PI) / 180, x = l * Math.cos(r), y = l * Math.sin(r); return `M${-x} ${-y} L${x} ${y}`; }).join(' ');
      return <path d={arms} fill="none" stroke={color} strokeWidth={l * 0.07} strokeLinecap="round" {...extra} />;
    }
    case 'dot': return <path d={`M${l / 2} 0 A${l / 2} ${l / 2} 0 1 1 ${-l / 2} 0 A${l / 2} ${l / 2} 0 1 1 ${l / 2} 0 Z`} fill={color} {...extra} />;
    case 'ring': return <path d={`M${l / 2} 0 A${l / 2} ${l / 2} 0 1 1 ${-l / 2} 0 A${l / 2} ${l / 2} 0 1 1 ${l / 2} 0 Z`} fill="none" stroke={color} strokeWidth={l * 0.06} {...extra} />;
    case 'plus': return <path d={`M${-l} 0 L${l} 0 M0 ${-l} L0 ${l}`} fill="none" stroke={color} strokeWidth={l * 0.14} {...extra} />;
    default: return null;
  }
};

export interface StarProps {
  /** its centre, fractions of W and H (usually on or past a corner) and its arm length (radius for dot and ring), in W */
  cx: number;
  cy: number;
  length: number;
  color: string;
  /** a soft-focus shape (the dark beats'): blur as a fraction of W, no shadow */
  soft?: number;
  /** the down-left shadow off its edges (default true on paper) */
  shadow?: boolean;
  /** which shape (default the taste's, on paper or `dark`; needle without a taste) */
  kind?: CornerKind;
  taste?: ExplainerTaste;
  dark?: boolean;
}

/** A corner shape with its down-left shadow: the taste's kind (needle stars for pin 1119), or `kind`. */
export const Star: React.FC<StarProps> = ({ cx, cy, length, color, soft = 0, shadow = soft === 0, kind, taste, dark }) => {
  const { width: W, height: H } = useVideoConfig();
  const shape = kind ?? (taste ? (dark ? taste.shapes.cornerOnDark : taste.shapes.corner) : 'needle');
  if (length <= 0.002 || shape === 'none') return null;
  const l = length * W, L = taste?.light;
  const side = (L?.castOffset[0] ?? -1) > 0 ? 1 : -1;
  const off = (L?.shapeOffset ?? 9 / 720) * W, blur = (L?.shapeBlur ?? 10 / 720) * W, alpha = L?.shapeAlpha ?? 0.38;
  return (
    <svg width={W} height={H} style={{ position: 'absolute', left: 0, top: 0, overflow: 'visible', pointerEvents: 'none' }}>
      <g transform={`translate(${cx * W} ${cy * H})`}>
        {shadow && <g opacity={alpha} transform={`translate(${side * off} ${off})`} style={{ filter: `blur(${blur.toFixed(1)}px)` }}>{shapeEl(shape, l, '#000')}</g>}
        <g style={{ filter: soft > 0 ? `blur(${(soft * W).toFixed(1)}px)` : undefined }}>{shapeEl(shape, l, color)}</g>
      </g>
    </svg>
  );
};

/** How big each kind is drawn for the same `length`, so a length means the same reach into the frame whatever the
 *  taste's shape: a needle's thin tips run the whole length, a dot or an asterisk would fill the corner at it. */
const REACH: Record<CornerKind, number> = { needle: 1, sparkle: 0.6, asterisk: 0.4, dot: 0.3, ring: 0.35, plus: 0.4, none: 0 };

/** The taste's corner shape on paper or dark, in the taste's colour, `length` being its reach (a needle's arm):
 *  `<Corner taste cx cy length dark?>`. */
export const Corner: React.FC<Omit<StarProps, 'color'> & { taste: ExplainerTaste; color?: string }> = ({ taste, dark, color, soft, ...rest }) => {
  const c = color ?? (dark ? taste.starOnDark : taste.star);
  if (!c) return null;
  const kind = rest.kind ?? (dark ? taste.shapes.cornerOnDark : taste.shapes.corner);
  return <Star {...rest} length={rest.length * REACH[kind]} taste={taste} dark={dark} color={c} soft={soft ?? (dark ? 0.03 : 0)} />;
};

/** The circle wipe: a hard black disc from (cx, cy), `speed` W of radius a frame from `t0` (0.115 measured, so it covers
 *  the frame in about 8 frames). Children (the next beat) show inside it. */
export const CircleWipe: React.FC<{ f: number; t0: number; cx: number; cy: number; color?: string; speed?: number; radii?: number[]; children?: React.ReactNode }> = ({ f, t0, cx, cy, color = '#000', speed = 0.115, radii, children }) => {
  const { width: W, height: H } = useVideoConfig();
  if (f < t0) return null;
  // an eased iris reads its radius off the table (pin 933: 54, 190, 355, 559, 700 px at 720), else a constant speed
  const r = (radii?.length ? radii[Math.min(radii.length - 1, f - t0)]! + Math.max(0, f - t0 - radii.length + 1) * 0.2 : 0.01 + speed * (f - t0)) * W;
  return (
    <div style={{ position: 'absolute', inset: 0, clipPath: `circle(${r.toFixed(1)}px at ${(cx * W).toFixed(1)}px ${(cy * H).toFixed(1)}px)`, background: color }}>
      {children}
    </div>
  );
};

/** A blinds wipe (not from a reference): `bands` horizontal bands slide shut across the frame, alternately from the
 *  left and the right, each over `speed` frames and one frame after the band above. Children show inside the bands. */
export const BlindsWipe: React.FC<{ f: number; t0: number; color?: string; speed?: number; bands?: number; children?: React.ReactNode }> = ({ f, t0, color = '#000', speed = 7, bands = 6, children }) => {
  const { width: W, height: H } = useVideoConfig();
  if (f < t0) return null;
  const bh = H / bands;
  let d = '';
  for (let i = 0; i < bands; i++) {
    const t = clamp01((f - t0 - i) / speed), w = W * (1 - (1 - t) ** 3);
    if (w < 0.5) continue;
    const x0 = i % 2 === 0 ? 0 : W - w, y0 = i * bh;
    d += `M${x0.toFixed(1)} ${y0.toFixed(1)}h${w.toFixed(1)}v${(bh + 1).toFixed(1)}h${(-w).toFixed(1)}Z`;
  }
  if (!d) return null;
  return <div style={{ position: 'absolute', inset: 0, clipPath: `path('${d}')`, background: color }}>{children}</div>;
};

/** The taste's wipe from beat to beat (`cut` draws children from `t0` with no wipe). */
export const Wipe: React.FC<{ taste: ExplainerTaste; f: number; t0: number; cx?: number; cy?: number; color?: string; kind?: WipeKind; children?: React.ReactNode }> = ({ taste, f, t0, cx = 0.5, cy = 0.5, color, kind, children }) => {
  const k = kind ?? taste.transition.wipe, c = color ?? taste.dark, { speed, bands, radii } = taste.transition;
  if (k === 'circle') return <CircleWipe f={f} t0={t0} cx={cx} cy={cy} color={c} speed={speed} radii={radii}>{children}</CircleWipe>;
  if (k === 'blinds') return <BlindsWipe f={f} t0={t0} color={c} speed={speed} bands={bands}>{children}</BlindsWipe>;
  return f < t0 ? null : <AbsoluteFill style={{ background: c }}>{children}</AbsoluteFill>;
};

/** A barcode: seeded bars, the small print under an object. */
export const Barcode: React.FC<{ seed?: string; width?: number; height?: number; color?: string }> = ({ seed = 'bc', width = 220, height = 46, color = '#111' }) => {
  const bars: number[] = [];
  let h = 0;
  for (const c of seed) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  for (let i = 0; i < 46; i++) { h = (h * 1103515245 + 12345) >>> 0; bars.push(1 + ((h >> 16) % 4)); }
  const total = bars.reduce((a, b) => a + b, 0) * 1.6;
  let x = 0;
  return (
    <svg width={width} height={height} viewBox={`0 0 ${total} 10`} preserveAspectRatio="none">
      {bars.map((b, i) => { const r = i % 2 === 0 ? <rect key={i} x={x} y={0} width={b} height={10} fill={color} /> : null; x += b * (i % 2 ? 1.2 : 1); return r; })}
    </svg>
  );
};

/** A small wordmark at the top centre (not in the measured reference; the agency reels carry one). */
export const Wordmark: React.FC<{ text: string; taste: ExplainerTaste }> = ({ text, taste }) => {
  const { width: W } = useVideoConfig();
  return (
    <div style={{ position: 'absolute', top: W * 0.05, left: 0, right: 0, textAlign: 'center', fontFamily: taste.font, fontWeight: 800, fontSize: W * 0.026,
      letterSpacing: '0.04em', lineHeight: 0.9, color: taste.ink, textTransform: 'uppercase' }}>{text}</div>
  );
};

/** A local patch of graph paper around an object (pin 971 S2, S4): dashed grey lines with a dot at each crossing, its
 *  edge feathered to nothing. Box and cell in fractions of W and H; `opacity` to fade it in with its beat. */
export const GridPatch: React.FC<{ x: number; y: number; w: number; h: number; cell?: [number, number]; color?: string; dot?: string; opacity?: number }> = ({ x, y, w, h, cell = [0.093, 0.036], color = '#b0b0b0', dot = '#8a8a8a', opacity = 1 }) => {
  const { width: W, height: H } = useVideoConfig();
  const pw = w * W, ph = h * H, cw = cell[0] * W, ch = cell[1] * H;
  const xs = Array.from({ length: Math.floor(pw / cw) + 1 }, (_, i) => i * cw), ys = Array.from({ length: Math.floor(ph / ch) + 1 }, (_, i) => i * ch);
  return (
    <svg width={pw} height={ph} style={{ position: 'absolute', left: x * W, top: y * H, opacity, maskImage: 'radial-gradient(ellipse 50% 50% at 50% 50%, #000 55%, transparent 100%)', WebkitMaskImage: 'radial-gradient(ellipse 50% 50% at 50% 50%, #000 55%, transparent 100%)' }}>
      {xs.map((v) => <line key={`v${v}`} x1={v} y1={0} x2={v} y2={ph} stroke={color} strokeWidth={W * 0.002} strokeDasharray={`${W * 0.008} ${W * 0.006}`} />)}
      {ys.map((v) => <line key={`h${v}`} x1={0} y1={v} x2={pw} y2={v} stroke={color} strokeWidth={W * 0.002} strokeDasharray={`${W * 0.008} ${W * 0.006}`} />)}
      {xs.flatMap((a) => ys.map((b) => <circle key={`${a}-${b}`} cx={a} cy={b} r={W * 0.0055} fill={dot} />))}
    </svg>
  );
};

/** The grey S-band behind a beat (pin 933 B4, B6, B11): a flat, thick curve from the top edge to the bottom, drawn on
 *  from the top at about 0.3 H a frame (full in 4 frames). `t0` its first frame. */
export const Band: React.FC<{ f: number; t0: number; color?: string; width?: number; mirror?: boolean }> = ({ f, t0, color = '#bdb8b3', width = 0.22, mirror }) => {
  const { width: W, height: H } = useVideoConfig();
  if (f < t0) return null;
  // the measured centre line (rows y 60, 200, 400, 1000, 1200 at 1280), as one smooth Catmull-Rom curve
  const pts: [number, number][] = [[0.17, -0.08], [0.23, 0.047], [0.36, 0.156], [0.45, 0.31], [0.58, 0.78], [0.75, 0.94], [0.86, 1.08]];
  const P = pts.map(([px, py]) => [(mirror ? 1 - px : px) * W, py * H] as const);
  let d = `M${P[0]![0]} ${P[0]![1]}`;
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[Math.max(0, i - 1)]!, p1 = P[i]!, p2 = P[i + 1]!, p3 = P[Math.min(P.length - 1, i + 2)]!;
    d += ` C${p1[0] + (p2[0] - p0[0]) / 6} ${p1[1] + (p2[1] - p0[1]) / 6} ${p2[0] - (p3[0] - p1[0]) / 6} ${p2[1] - (p3[1] - p1[1]) / 6} ${p2[0]} ${p2[1]}`;
  }
  const drawn = clamp01((f - t0 + 1) * 0.3 / 1.12);
  return (
    <svg width={W} height={H} style={{ position: 'absolute', left: 0, top: 0 }}>
      <path d={d} fill="none" stroke={color} strokeWidth={width * W} pathLength={1} strokeDasharray={`${drawn} 1`} />
    </svg>
  );
};

/** The taste's textures over the whole frame (taste.texture): draw it last. The files are tastes/explainer/textures, served
 *  from the effect's public folder at `base` (link it: `ln -s ../../../kit/explainer/textures public/explainer-textures`).
 *  Grain jumps to a new offset every other frame, like film. */
export const Texture: React.FC<{ taste: ExplainerTaste; base?: string; dark?: boolean }> = ({ taste, base = 'explainer-textures', dark }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const t = taste.texture, tile = Math.round(W * 0.474);
  const url = (n: string) => `url(${staticFile(`${base}/${n}.png`)})`;
  const step = Math.floor(f / 2), jx = ((step * 7919) % 997) / 997, jy = ((step * 104729) % 991) / 991;
  const layer = (name: string, opacity: number, blend: React.CSSProperties['mixBlendMode'], pos = '0px 0px', size: number | string = tile) => opacity > 0 && (
    <AbsoluteFill key={name} style={{ pointerEvents: 'none', backgroundImage: url(name), backgroundRepeat: 'repeat', backgroundSize: typeof size === 'number' ? `${size}px ${size}px` : size, backgroundPosition: pos, mixBlendMode: blend, opacity }} />
  );
  return (
    <>
      {layer('paper', t.paper * (dark ? 0.4 : 1), 'multiply')}
      {layer('halftone', t.halftone, 'multiply', '0px 0px', Math.round(W * 0.25))}
      {/* the rest blend normally, so they print over the type and the objects as well as the paper */}
      {layer('ink', t.ink, 'normal')}
      {/* a real scanned halftone screen, full frame, hard-light: neutral at its mid grey, so its dots darken the paper
          and lift specks out of black type alike; it jumps a little every 4 frames, like a page re-scanned */}
      {t.scan > 0 && <AbsoluteFill style={{ pointerEvents: 'none', backgroundImage: `url(${staticFile(`${base}/scans/scan-halftone.jpg`)})`, backgroundSize: '104% 104%',
        backgroundPosition: `${(-0.02 * W + ((Math.floor(f / 4) * 37) % 9) - 4).toFixed(0)}px ${(-0.02 * H + ((Math.floor(f / 4) * 53) % 9) - 4).toFixed(0)}px`, mixBlendMode: 'hard-light', opacity: t.scan }} />}
      {/* moire: one full frame (no tile, so no repeating stripe), a little larger than the frame, drifting */}
      {layer('moire', t.moire, 'normal', `${(-0.04 * W + f * 0.25).toFixed(1)}px ${(-0.03 * H + f * 0.6).toFixed(1)}px`, '111% 109%')}
      {layer('grain', t.grain, 'normal', `${Math.round(jx * tile)}px ${Math.round(jy * tile)}px`, Math.round(W * 0.36))}
    </>
  );
};

// What a taste is. The explainer engine (stage.tsx, type.tsx, props.tsx) draws every reel of the family; a taste is the
// data that makes one reel look like its reference: colours and fonts, how the type writes on and fades, how objects
// enter and leave, how strong the shadows and glow are, what sits in the corners, how one beat hands over to the next.
//
// One taste per reference, in tastes/<name>.ts, with a row in TASTES.md. Its numbers come from the kinetograph-taste-clone
// skill's measured spec or gene of that reference (`meta.source` names it). A number nobody has measured yet is
// inherited from `BASE` (measured from pin 1119) and the taste says so with `meta.measured: false`.
//
// Lengths are fractions of the frame width W (or height H where named), times are frames at 30 fps.

export interface TasteMeta {
  /** the file name and the key in TASTES */
  id: string;
  title: string;
  /** one line an agent reads to choose: the subject and tone this taste suits */
  useWhen: string;
  /** where its numbers come from: a reference pin id, or 'original' for one made for this kit */
  source: string;
  /** every number below read off the reference frame by frame (false: some are inherited from BASE) */
  measured: boolean;
  /** a rendered still or reel of the taste, relative to the repo root */
  preview?: string;
  /** its reference's beat layouts (layouts.tsx), in the order the reference uses them */
  layouts?: string[];
}

/** A letter of the lead on its first frames after landing: scale, lift in em, turn in degrees. */
export interface Hop { s: number; y: number; r: number }

export interface TasteText {
  /** how the lead arrives: letter by letter with the hop (1119), or word by word, fading up out of a blur over `fade`
   *  frames and moving along `leadBob` (em, down positive, a frame each; 971: up from below, past, back) */
  leadMode: 'letters' | 'words';
  leadBob: number[];
  /** the lead's size, letter spacing (em) and letters a frame by default */
  leadSize: number;
  leadTracking: number;
  leadRate: number;
  /** the pose of each letter on its first frames; after the last it is upright */
  hop: Hop[];
  /** the keyword: letter spacing (em), the gap between words (em), line height */
  keyTracking: number;
  keyGap: number;
  keyLineHeight: number;
  /** each keyword word fades up over `fade` frames out of a blur of `blur` W */
  fade: number;
  blur: number;
  /** words pop in whole by default instead of fading */
  pop: boolean;
  /** a word's opacity on its first frame (933: 0.3), and how far below its line it starts (em) and the share of that
   *  kept a frame as it rises (933: 0.3 em, 0.75); 0 for no rise */
  fadeFrom: number;
  rise: number;
  riseKeep: number;
  /** a spring bob as a word lands: its offset in em (down positive) on each frame from its start; empty for none.
   *  `bobLag` frames later for each accent-coloured word, `bobGain` times bigger */
  bob: number[];
  bobLag: number;
  bobGain: number;
}

export interface TasteMotion {
  /** entrances: the share of the distance left kept each frame (a rise from the bottom, a slide from a side) */
  riseKeep: number;
  slideKeep: number;
  /** a risen object creeps this much bigger over the 20 frames after it lands */
  riseCreep: number;
  /** a push exit: k (W per frame squared) for the lead, the keyword and the object, and the frames each starts after the push */
  push: [number, number, number];
  pushLag: [number, number, number];
  /** a dissolve wave: the front's speed (W a frame) and the frames a letter takes to fade once reached */
  waveSpeed: number;
  waveFade: number;
  /** a sprung entrance (`enter="spring"`): the object's scale on each frame from its start, then 1 */
  spring: number[];
}

/** The camera: moves of the whole beat about the frame centre. Numbers measured off pins 933 and 971 (BASE). */
export interface TasteCamera {
  /** a push-in: scale 1 + amount (1 - keep^n) + drift n */
  pushAmount: number;
  pushKeep: number;
  pushDrift: number;
  /** a pan between scenes: pure translation by the gap; speed ramps up over `panRise` frames (((n + 1) / (rise + 1))^1.5), then
   *  keeps `panKeep` of itself each frame */
  panRise: number;
  panKeep: number;
  /** a roll in: from `rollFrom` degrees, keeping `rollKeep` each frame; a roll out: a n + b n^2 degrees */
  rollFrom: number;
  rollKeep: number;
  rollOut: [number, number];
  /** arrival focus: blur (W) on the first frame of a move, sharp after `arriveFrames` (linear) */
  arriveBlur: number;
  arriveFrames: number;
  /** a zoom-out exit: the scale on each frame; the scene fades to paper from `zoomFade[0]` to `zoomFade[1]` frames */
  zoomOut: number[];
  zoomFade: [number, number];
  /** a flicker exit: brightness on each frame */
  flicker: number[];
}

export interface TasteLight {
  /** the cast shadow: strength, offset (W, H) and blur. The offset's sign is the light's side: down-left for a top-right
   *  light (1119), down-right for a top-left one (933, 971); corner shapes and ground bands follow it */
  castAlpha: number;
  castOffset: [number, number];
  castBlur: number;
  /** the ground band under an object on the floor: strength at the contact */
  groundAlpha: number;
  /** a corner shape's own shadow: strength, offset and blur, in W */
  shapeAlpha: number;
  shapeOffset: number;
  shapeBlur: number;
  /** the bloom of type on dark beats: tight and wide halo radii (em) and a strength multiplier */
  glowTight: number;
  glowWide: number;
  glowStrength: number;
}

/** The corner shapes. `needle` is measured (pin 1119); the others are drawn for tastes of their own. */
export type CornerKind = 'needle' | 'sparkle' | 'asterisk' | 'dot' | 'ring' | 'plus' | 'none';

export interface TasteShapes {
  /** the shape on paper beats and on dark beats */
  corner: CornerKind;
  cornerOnDark: CornerKind;
  /** a shape grows in keeping this share of the length still to grow each frame, then breathes this much */
  grow: number;
  breathe: number;
  /** the small print under an object */
  smallPrint: 'barcode' | 'none';
}

/** How one beat hands over to the next when it does not just cut. */
export type WipeKind = 'circle' | 'blinds' | 'cut';

export interface TasteTransition {
  wipe: WipeKind;
  /** circle: radius growth in W a frame; blinds: frames for each band to close */
  speed: number;
  /** blinds: how many bands */
  bands: number;
  /** circle: the radius (W) on each frame instead of a constant speed, an eased iris; empty for linear */
  radii: number[];
}

/** Textures laid over the finished frame, type included, each an opacity (0 for none): paper fibre (multiply, on the
 *  paper), ink wear (pale flecks breaking up dark type and objects), film grain (dark and light specks, moving), a
 *  scanned halftone screen over everything (hard-light), a procedural halftone dot screen (multiply). Original procedural files in textures/ (tools/textures.py). Not measured: the references are near clean
 *  (971 grain about 1 luma), so these are a choice of the taste, for a printed, filmed feel. */
export interface TasteTexture {
  paper: number;
  ink: number;
  grain: number;
  /** a real scanned halftone screen over everything (hard-light): textures/scans/scan-halftone.jpg */
  scan: number;
  /** curved moire bands over everything, drifting (textures/moire.png) */
  moire: number;
  halftone: number;
}

export interface ExplainerTaste {
  name: string;
  meta: TasteMeta;
  /** the paper, and the dark interlude beats */
  paper: string;
  dark: string;
  /** a vignette on the paper, 0..1 */
  vignette: number;
  /** graph paper behind everything */
  grid: boolean;
  /** the grid's cell (W), line colour and strength */
  gridCell?: number;
  gridInk?: string;
  gridStrength?: number;
  /** the small lead line, on paper and on dark */
  ink: string;
  inkOnDark: string;
  /** the keyword; `keywordOnDark` is its lifted core on dark beats, where it blooms */
  keyword: string;
  keywordOnDark: string;
  /** how the accent shows: the keyword's own colour, or a highlighter behind black type */
  accentMode: 'ink' | 'highlight';
  /** the colour of a keyword line marked `plain` (default the lead's ink; 1061 sets its grey second lines) */
  muted?: string;
  /** the weight of plain words (default the keyword's; 933 sets its small words' 600 beside the 900 accent) */
  mutedWeight?: number;
  highlight: string;
  font: string;
  /** the lead's own family and slant when it differs from the keyword's (971: a condensed face, upright) */
  leadFont?: string;
  leadItalic?: boolean;
  leadWeight: number;
  keyWeight: number;
  italic: boolean;
  /** corner shapes' colour on paper and on dark beats (null for none) */
  star: string | null;
  starOnDark: string | null;
  text: TasteText;
  motion: TasteMotion;
  light: TasteLight;
  shapes: TasteShapes;
  transition: TasteTransition;
  camera: TasteCamera;
  texture: TasteTexture;
}

/** The measured numbers of pin 1119: what a taste inherits for anything its own reference has not measured. */
export const BASE: Pick<ExplainerTaste, 'text' | 'motion' | 'light' | 'shapes' | 'transition' | 'camera' | 'texture'> = {
  texture: { paper: 0, ink: 0, grain: 0, scan: 0, moire: 0, halftone: 0 },
  text: {
    leadMode: 'letters', leadBob: [],
    leadSize: 0.038, leadTracking: -0.01, leadRate: 1,
    hop: [{ s: 0.7, y: 0.4, r: -10 }, { s: 0.8, y: 0.25, r: -6 }, { s: 0.9, y: 0.1, r: -3 }],
    keyTracking: -0.04, keyGap: 0.24, keyLineHeight: 1,
    fade: 8, blur: 10 / 720, pop: false, fadeFrom: 0, rise: 0, riseKeep: 0.75,
    // no bob in pin 1119; pin 933's measured bob (B12 "DM", cap 57 px at 720) when a taste turns it on
    bob: [], bobLag: 2, bobGain: 1.4,
  },
  motion: { riseKeep: 0.88, slideKeep: 0.86, riseCreep: 0.03, push: [0.005, 0.0027, 0.01], pushLag: [0, 1, 4], waveSpeed: 0.046, waveFade: 3,
    // pin 933 B7: the wordmark's spring, overshoot +11.6% at +4, undershoot -4.3% at +10, rest by +22
    spring: [0.31, 0.665, 0.993, 1.076, 1.116, 1.116, 1.09, 1.04, 1.0, 0.98, 0.957, 0.96, 0.965, 0.97, 0.975, 0.98, 0.985, 0.99, 0.993, 0.996, 0.998, 1] },
  light: {
    castAlpha: 0.4, castOffset: [-0.015, 0.012], castBlur: 0.025, groundAlpha: 0.55,
    shapeAlpha: 0.38, shapeOffset: 9 / 720, shapeBlur: 10 / 720,
    glowTight: 0.06, glowWide: 0.3, glowStrength: 1,
  },
  shapes: { corner: 'needle', cornerOnDark: 'needle', grow: 0.75, breathe: 0.1, smallPrint: 'none' },
  transition: { wipe: 'circle', speed: 0.115, bands: 6, radii: [] },
  camera: {
    // pin 933 B1: 1.00 to 1.70 in 35 frames, fitted within 0.033 of scale on every measured frame
    pushAmount: 0.4, pushKeep: 0.78, pushDrift: 0.008,
    // pin 971: peak 132-140 px a frame at 720 after 4 frames, then 0.88 a frame
    panRise: 4, panKeep: 0.88,
    // pin 933 B5 (-65 deg, 0.895) and B4's exit (2.5, 7, 10.9, 16.3, 22.6, 28 deg)
    rollFrom: -65, rollKeep: 0.895, rollOut: [2.94, 0.344],
    // pin 971 S2: sigma 14 px at 720 to sharp over 14 frames
    arriveBlur: 14 / 720, arriveFrames: 14,
    // pin 971 S2 exit
    zoomOut: [1, 0.985, 0.97, 0.92, 0.867, 0.82, 0.76, 0.7, 0.67, 0.655, 0.64, 0.62, 0.6, 0.58, 0.565, 0.55], zoomFade: [6, 18],
    // pin 933 B1 exit
    flicker: [1, 0.51, 0.01, 0.5, 1, 0.49],
  },
};

type Section = 'text' | 'motion' | 'light' | 'shapes' | 'transition' | 'camera' | 'texture';
export type TasteInput = Omit<ExplainerTaste, Section | 'name'> & { [K in Section]?: Partial<ExplainerTaste[K]> };

/** A taste from its own numbers, each section filled in from BASE where the reference has not set it. */
export const defineTaste = (t: TasteInput): ExplainerTaste => ({
  ...t,
  name: t.meta.id,
  text: { ...BASE.text, ...t.text },
  motion: { ...BASE.motion, ...t.motion },
  light: { ...BASE.light, ...t.light },
  shapes: { ...BASE.shapes, ...t.shapes },
  transition: { ...BASE.transition, ...t.transition },
  camera: { ...BASE.camera, ...t.camera },
  texture: { ...BASE.texture, ...t.texture },
});

// The explainer's type. Its numbers come from the taste (taste.text, taste.light); as measured for BASE (pin 1119, 30 fps,
// sizes as fractions of the frame width W):
//
//   Lead     the small line: medium italic, 0.038 W, near-black (white on dark). It writes on one character at a time,
//            about one a frame (0.8 to 2.5 a frame across the reference's beats), spaces taking no time. Each letter lands
//            at 0.7 scale, 0.4 em up and turned -10 degrees and settles over 3 frames (0.8 / 0.9 scale, 0.25 / 0.1 em),
//            so the line ripples as it writes.
//   Keyword  the big words: extra-bold italic, tight (-0.04 em, line height about 0.9), placed line by line flush left
//            with ragged starts. Each word fades up out of a blur over 8 frames (10 px at 720 wide to 0), words 3 to 8
//            frames apart; or, in a beat that wants punch, pops in whole on its frame.
//   On dark  both bloom: the colour's core is lifted (red to a pink, white stays white) and two halos sit behind it,
//            a tight one and a wide one, with the letters themselves a touch soft, like light rather than ink.
//   Exits    a dissolve wave left to right (`wave` in stage.tsx), a uniform fade, or a push (an `x` offset per frame).
//
// The keyword is drawn before the object, so the object covers part of it, but only ever the tail of the last line:
// the keyword must still read.

import React from 'react';
import { useCurrentFrame, useVideoConfig } from 'remotion';
import { makeGoogleFont } from '@kinetographdev/core/google-fonts';
import { clamp01, wave } from './stage.js';
import type { ExplainerTaste } from './taste.js';

const loaded = new Map<string, string>();
/** The family for a taste font at a weight: a Google font by name, else the name as given (a font loaded elsewhere). */
export function family(name: string, weight: number, italic: boolean): string {
  const key = `${name}|${weight}|${italic}`;
  let fam = loaded.get(key);
  if (!fam) {
    try { fam = makeGoogleFont(name.replace(/ /g, '')).loadFont(italic ? 'italic' : 'normal', { weights: [String(weight)] }).fontFamily; }
    catch { fam = name; }
    loaded.set(key, fam);
  }
  return fam;
}

const hexRgb = (hex: string) => { const n = parseInt(hex.replace('#', '').slice(0, 6), 16); return `${(n >> 16) & 255},${(n >> 8) & 255},${n & 255}`; };
/** The bloom behind type on a dark beat: a tight halo and a wide one in the type's colour. */
const bloom = (taste: ExplainerTaste, color: string, px: number, strength = 1) => {
  const { glowTight, glowWide, glowStrength } = taste.light, k = strength * glowStrength;
  return `0 0 ${(px * glowTight).toFixed(1)}px rgba(${hexRgb(color)},${Math.min(1, 0.9 * k).toFixed(2)}), 0 0 ${(px * glowWide).toFixed(1)}px rgba(${hexRgb(color)},${Math.min(1, 0.6 * k).toFixed(2)})`;
};

/** A line's box: from its anchor at `x` (fraction of W), aligned left, centre or right, full width so it never wraps. */
export const anchor = (x: number, align: 'left' | 'center' | 'right', W: number): React.CSSProperties =>
  align === 'left' ? { left: x * W, justifyContent: 'flex-start' }
    : { left: (x - (align === 'center' ? 0.5 : 1)) * W, width: W, justifyContent: align === 'center' ? 'center' : 'flex-end' };

export interface LeadProps {
  taste: ExplainerTaste;
  text: string;
  /** the line's anchor (its left edge, centre or right edge, by `align`) and its middle, fractions of W and H */
  x: number;
  y: number;
  align?: 'left' | 'center' | 'right';
  /** the frame its first letter lands, and letters a frame (default the taste's) */
  at: number;
  rate?: number;
  /** a dark beat: white type that blooms */
  dark?: boolean;
  /** a dissolve wave's first frame */
  out?: number;
  /** an offset in W this frame (a push exit) */
  dx?: number;
  /** a fraction of W (default the taste's) */
  size?: number;
}

/** The small lead line, written on letter by letter with the settling hop. */
export const Lead: React.FC<LeadProps> = ({ taste, text, x, y, align = 'left', at, rate = taste.text.leadRate, dark, out, dx = 0, size = taste.text.leadSize }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const px = W * size;
  const color = dark ? taste.inkOnDark : taste.ink;
  let n = 0;
  const T = taste.text, words = T.leadMode === 'words';
  // in words mode every letter of a word takes the word's first letter's frame
  let wordAt = at;
  const chars = [...text].map((c, i, all) => {
    const t = at + Math.floor(n / rate);
    if (c !== ' ' && (i === 0 || all[i - 1] === ' ')) wordAt = t;
    if (c !== ' ') n++;
    return { c, at: c === ' ' ? -1 : words ? wordAt : t };
  });
  const start = align === 'left' ? x : align === 'center' ? x - text.length * size * 0.27 : x - text.length * size * 0.54;
  return (
    <div style={{ position: 'absolute', ...anchor(x + dx, align, W), top: y * H - px * 0.62,
      display: 'flex', whiteSpace: 'pre', fontFamily: family(taste.leadFont ?? taste.font, taste.leadWeight, taste.leadItalic ?? taste.italic),
      fontStyle: taste.leadItalic ?? taste.italic ? 'italic' : 'normal', fontWeight: taste.leadWeight, fontSize: px, lineHeight: 1.2, letterSpacing: `${taste.text.leadTracking}em`, color,
      textShadow: dark ? bloom(taste, color, px, 0.7) : undefined }}>
      {chars.map((ch, i) => {
        if (ch.c === ' ') return <span key={i}>{' '}</span>;
        const a = f - ch.at;
        if (a < 0) return <span key={i} style={{ opacity: 0 }}>{ch.c}</span>;
        const hop = words ? { s: 1, y: -(T.leadBob[a] ?? 0), r: 0 } : (T.hop[a] ?? { s: 1, y: 0, r: 0 });
        const k = words ? T.fadeFrom + (1 - T.fadeFrom) * clamp01((a + 1) / T.fade) : 1;
        const soft = words ? (1 - k) * T.blur * W : 0;
        const gone = wave(f, out, start + i * size * 0.55, start, taste.motion.waveSpeed, taste.motion.waveFade);
        return (
          <span key={i} style={{ display: 'inline-block', transformOrigin: '50% 100%', transform: `translateY(${(-hop.y * px).toFixed(1)}px) scale(${hop.s}) rotate(${hop.r}deg)`,
            opacity: k * (1 - gone), filter: gone + soft > 0 ? `blur(${(gone * px * 0.25 + soft).toFixed(1)}px)` : undefined }}>{ch.c}</span>
        );
      })}
    </div>
  );
};

export interface KeyLine {
  words: string[];
  /** the line's left edge and middle, fractions of W and H (lines start ragged, a few hundredths apart) */
  x: number;
  y: number;
  /** the frame each word starts to arrive */
  at: number[];
  /** plain words, in `taste.muted` (or the lead's ink) at `taste.mutedWeight`: the whole line (true) or the words at
   *  these indexes (933 mixes both on one line: "ideas and"). false marks an accent line that bobs late and wide beside
   *  plain ones; unset for an ordinary keyword line */
  plain?: boolean | number[];
  /** where `x` anchors the line (default left) */
  align?: 'left' | 'center' | 'right';
}

export interface KeywordProps {
  taste: ExplainerTaste;
  lines: KeyLine[];
  /** the font size, a fraction of W (0.087 to 0.215 in the reference: bigger for fewer, shorter words) */
  size: number;
  /** pop each word in whole instead of the blur fade (default the taste's) */
  pop?: boolean;
  dark?: boolean;
  /** a dissolve wave's first frame, or a uniform fade [from, to] */
  out?: number;
  fade?: [number, number];
  dx?: number;
}

/** The big keyword lines, word by word. */
export const Keyword: React.FC<KeywordProps> = ({ taste, lines, size, pop = taste.text.pop, dark, out, fade, dx = 0 }) => {
  const T = taste.text;
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const px = W * size;
  const color = dark ? taste.keywordOnDark : taste.accentMode === 'highlight' ? taste.ink : taste.keyword;
  const faded = fade ? 1 - clamp01((f - fade[0]) / (fade[1] - fade[0])) : 1;
  return (
    <>
      {lines.map((ln, li) => {
        let chars = 0;
        return (
          <div key={li} style={{ position: 'absolute', ...anchor(ln.x + dx, ln.align ?? 'left', W), top: ln.y * H - px * 0.55, display: 'flex', columnGap: px * T.keyGap, whiteSpace: 'pre',
            fontFamily: family(taste.font, taste.keyWeight, taste.italic), fontStyle: taste.italic ? 'italic' : 'normal', fontWeight: taste.keyWeight,
            fontSize: px, lineHeight: T.keyLineHeight, letterSpacing: `${T.keyTracking}em`, color, textShadow: dark ? bloom(taste, color, px) : undefined, filter: dark ? `blur(${(W / 720 * 0.7).toFixed(2)}px)` : undefined }}>
            {ln.words.map((word, wi) => {
              const t = f - (ln.at[wi] ?? ln.at[0]!);
              const k = pop ? (t >= 0 ? 1 : 0) : t < 0 ? 0 : T.fadeFrom + (1 - T.fadeFrom) * clamp01(t / T.fade);
              // the spring bob (taste.text.bob): a late accent line starts `bobLag` frames later and swings `bobGain` wider
              // a taste with both moves (933) bobs on dark beats and rises on paper ones
              const plain = ln.plain === true || (Array.isArray(ln.plain) && ln.plain.includes(wi));
              const late = ln.plain === false || (Array.isArray(ln.plain) && !plain), nb = dark ? T.bob.length : 0;
              const bob = nb && t >= 0 ? (T.bob[Math.min(nb - 1, Math.max(0, t - (late ? T.bobLag : 0)))] ?? 0) * (late ? T.bobGain : 1) : 0;
              const rise = T.rise && !nb && t >= 0 ? T.rise * T.riseKeep ** t : 0;
              const x0 = ln.x + chars * size * 0.56;
              chars += word.length + 1;
              const gone = wave(f, out, x0, 0.1, taste.motion.waveSpeed, taste.motion.waveFade);
              const blur = (pop ? 0 : (1 - k) * T.blur * W) + gone * 8;
              const hi = taste.accentMode === 'highlight' && !dark ? clamp01((t - 5) / 9) : 0;
              return (
                <span key={wi} style={{ display: 'inline-block', ...(plain ? { color: dark ? taste.inkOnDark : taste.muted ?? taste.ink, fontWeight: taste.mutedWeight ?? taste.keyWeight,
                  fontFamily: family(taste.font, taste.mutedWeight ?? taste.keyWeight, taste.italic) } : {}), transform: bob + rise ? `translateY(${((bob + rise) * px).toFixed(1)}px)` : undefined, opacity: k * faded * (1 - gone), filter: blur > 0.3 ? `blur(${blur.toFixed(1)}px)` : undefined,
                  ...(hi > 0 ? { backgroundImage: `linear-gradient(${taste.highlight}, ${taste.highlight})`, backgroundRepeat: 'no-repeat', backgroundPosition: `0px ${(px * 0.18).toFixed(1)}px`,
                    backgroundSize: `${(hi * 100).toFixed(1)}% ${(px * 0.8).toFixed(1)}px`, paddingLeft: px * 0.08, paddingRight: px * 0.08, marginLeft: -px * 0.08, marginRight: -px * 0.08 } : {}) }}>{word}</span>
              );
            })}
          </div>
        );
      })}
    </>
  );
};

/** A small paragraph typed on (pin 971: about 3.3 characters a frame, centred lines, regular weight, the ink colour). */
export const Paragraph: React.FC<{ taste: ExplainerTaste; lines: string[]; x: number; y: number; at: number; rate?: number; size?: number; align?: 'left' | 'center' | 'right' }> = ({ taste, lines, x, y, at, rate = 3.3, size = 0.027, align = 'center' }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const px = size * W;
  let shown = Math.max(0, Math.floor((f - at) * rate));
  return (
    <>
      {lines.map((ln, i) => {
        const part = ln.slice(0, Math.max(0, shown));
        shown -= ln.length;
        return (
          <div key={i} style={{ position: 'absolute', ...anchor(x, align, W), top: y * H + i * px * 1.4 - px * 0.6, display: 'flex', whiteSpace: 'pre',
            fontFamily: family('Inter', 400, false), fontWeight: 400, fontSize: px, lineHeight: 1.2, color: taste.ink }}>{part}</div>
        );
      })}
    </>
  );
};

// The archive taste: historical photographs brought to life, the old-film documentary look. Read off six technique
// reels; every number below is from those measurements.
//
// Rules, and the reel each comes from:
//   - a still photo becomes a shot: cut it into foreground, subject and background, fill the hole behind the subject,
//     and slide a camera so the layers move 3 : 1 : 0.6, the foreground out of focus, the move on twos
//     (DZsDDmvtNJP; kit/looks Parallax)
//   - it sits in a projector gate: a new position every 2nd frame, std about 1.1 px x / 1.7 px y at 1080 wide, and an
//     exposure flicker of about 0.024 stops every frame (Da3YpRipHuF; GateWeave, Flicker)
//   - light falls across it: a window-light plate multiplied at about 0.53 in its shadows, drifting slowly, and film
//     dust screened on top (DdKZ5oBpPCW; WindowLight, Dust)
//   - the documentary finish: a radial lens blur at the edges (not chromatic aberration), film dust, an offset vignette
//     twice as dark at the bottom, a slow push of about 0.2% a frame (DZFqNzwAqVa; EdgeBlur, Dust, Vignette)
//   - cut between two pictures on the fastest frame of one shared scale move, cubic-bezier(0.97, 0, 0.03, 1), on twos
//     (DaDhDFjAysT; CurveCut, Posterize 2)
//   - documents turn like paper (CC Page Turn, Fold Radius 50, back opacity 0.85) and the turn is posterized to
//     8 fps, hand-animated (Dafr0KjAkve; PageTurn, Posterize 3 at 24 fps, 4 at 30 fps)
//
// What the taste adds of its own: the photo printed as the process it was made with (a silvery daguerreotype plate, a
// warm albumen print, a salted paper print) with film grain; type that reads like a museum's archive (a book serif for
// what is said, a typewriter for dates, places and catalogue labels); and layouts made from the objects themselves (a
// plate in its brass mat, a page of an album, a catalogue tag).
//
// Legibility rules: light type only ever over the dark falloff of the vignette or a dark scrim; on paper (album page,
// tag) the type is dark ink. One text animation at a time.

export const ARCHIVE = {
  /** the dark around everything: soot, a warm black */
  soot: '#0d0b09',
  umber: '#241b14',
  /** velvet of a daguerreotype case */
  velvet: '#2b1416',
  /** brass of the mat */
  brass: '#b48c4c',
  brassDark: '#6e5226',
  /** type on dark: an off-white silver, never pure white */
  silver: '#eee6d6',
  /** a dimmer line on dark */
  ash: '#b9ae9a',
  /** album page and catalogue tag */
  paper: '#e8dfc9',
  paperDark: '#cdbf9f',
  /** ink on paper */
  ink: '#1c1611',
  /** the one accent: an accession-stamp oxblood red */
  stamp: '#9a2d20',
} as const;

/** Tones the photo is printed in: [shadow, highlight], blacks mapped to the first, whites to the second. */
export const PROCESS = {
  /** a silvered copper plate: near-neutral, a cool cast in the shadows, bright mirror highlights */
  daguerreotype: { dark: '#14130f', light: '#efe9dc', lo: 0.06, hi: 0.94, gamma: 0.95, grain: 0.05 },
  /** albumen print from a glass negative: warm brown-purple shadows, cream highlights */
  albumen: { dark: '#2a160d', light: '#f2e2c0', lo: 0.05, hi: 0.95, gamma: 1.0, grain: 0.06 },
  /** salted paper print from a paper negative: soft, matte, red-brown, low contrast */
  salted: { dark: '#3b2014', light: '#ead8b8', lo: 0.0, hi: 1.0, gamma: 1.1, grain: 0.08 },
  /** plain silver gelatin black and white */
  silver: { dark: '#0f0f0e', light: '#f1efe8', lo: 0.04, hi: 0.96, gamma: 1.0, grain: 0.06 },
} as const;
export type Process = keyof typeof PROCESS;

export const FONTS = {
  /** what is said: a book serif, roman and italic */
  serif: 'EB Garamond',
  /** dates, places, catalogue labels: a typewriter */
  type: 'Courier Prime',
} as const;

/** Frame steps: the parallax and curve-cut moves are on twos (12 fps from 24 / 15 from 30); page turns at 8 fps. */
export const STEP = { twos: 2, page: 4 } as const;

// The archive's type. Two faces only: a book serif for what is said (EB Garamond), a typewriter for what the archive
// records (Courier Prime: dates, places, catalogue numbers). The moves:
//
//   Dateline   the archive's record line: typewriter caps, tracked 0.18 em, typed one character a frame behind a
//              block caret that blinks out after the last letter; a short rule leads it
//   Develop    the headline comes up the way a print comes up in the developer tray: each line from blank paper-white
//              and soft (blur 0.12 em) to its full tone and sharp over 14 frames, lines 7 frames apart
//   Line       a plain line that fades up (the words around the one that moves)
//   Tag        a catalogue tag: a paper card with dark typewriter ink, a red accession number, dropped in
//
// Sizes are fractions of the frame width W. Light type only over the dark (the vignette's falloff, a Scrim); on paper
// the type is ink. One text animation at a time: start the next when the last has landed.
import React from 'react';
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from 'remotion';
import { family } from './shared/tastes/explainer/type.js';
import { ARCHIVE, FONTS } from './tokens.js';

const clamp01 = (t: number) => Math.min(1, Math.max(0, t));
const easeOut = (t: number) => 1 - (1 - clamp01(t)) ** 3;

export const serif = (weight = 500, italic = false) => family(FONTS.serif, weight, italic);
export const typewriter = (weight = 400) => family(FONTS.type, weight, false);

interface Place {
  /** anchor in fractions of W and H: the left edge (or centre/right by `align`) and the line's middle */
  x: number;
  y: number;
  /** font size, fraction of W */
  size: number;
  align?: 'left' | 'center' | 'right';
  color?: string;
  /** first frame */
  at: number;
  /** a frame from which it fades out over 6 frames */
  out?: number;
}

const box = (p: Place, W: number, H: number): React.CSSProperties => {
  const px = p.size * W;
  const align = p.align ?? 'left';
  const pos: React.CSSProperties = align === 'left' ? { left: p.x * W } : { left: (p.x - (align === 'center' ? 0.5 : 1)) * W, width: W, justifyContent: align === 'center' ? 'center' : 'flex-end' };
  return { position: 'absolute', ...pos, top: p.y * H - px * 0.62, display: 'flex', whiteSpace: 'pre', fontSize: px, lineHeight: 1.2 };
};
const gone = (f: number, out?: number) => (out === undefined ? 0 : clamp01((f - out) / 6));
/** a soft dark halo so light type holds on any part of a photo */
const halo = (W: number) => `0 ${(0.002 * W).toFixed(1)}px ${(0.012 * W).toFixed(1)}px rgba(8,6,4,0.85), 0 0 ${(0.03 * W).toFixed(1)}px rgba(8,6,4,0.55)`;

/** The record line: typewriter caps typed one character a frame, a caret, a lead rule. */
export const Dateline: React.FC<Place & { text: string; rate?: number; rule?: boolean }> = ({ text, rate = 1, rule = true, color = ARCHIVE.silver, ...p }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const a = f - p.at;
  if (a < 0) return null;
  const shown = Math.min(text.length, Math.floor(a * rate) + 1);
  const done = shown >= text.length;
  const caret = !done || (Math.floor((a - text.length / rate) / 6) % 2 === 0 && a - text.length / rate < 24);
  const px = p.size * W;
  const ruleW = rule ? clamp01(a / 6) * px * 1.6 : 0;
  return (
    <div style={{ ...box(p, W, H), alignItems: 'center', fontFamily: typewriter(700), fontWeight: 700, letterSpacing: '0.18em', color, textShadow: halo(W), opacity: 1 - gone(f, p.out) }}>
      {rule && <span style={{ display: 'inline-block', width: ruleW, height: Math.max(2, px * 0.08), background: color, marginRight: px * 0.5, boxShadow: halo(W) }} />}
      <span>{text.slice(0, shown).toUpperCase()}</span>
      <span style={{ display: 'inline-block', width: px * 0.62, height: px * 0.95, background: color, opacity: caret ? 0.85 : 0, marginLeft: px * 0.06 }} />
    </div>
  );
};

/** The headline develops, line by line: from paper-white and soft to its tone and sharp. */
export const Develop: React.FC<Omit<Place, 'y'> & { lines: string[]; y: number; leading?: number; italic?: boolean[]; weight?: number; stagger?: number; dur?: number; shadow?: boolean }> = ({ lines, leading = 1.12, italic = [], weight = 500, stagger = 7, dur = 14, color = ARCHIVE.silver, shadow = true, ...p }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const px = p.size * W;
  const g = gone(f, p.out);
  return (
    <>
      {lines.map((text, i) => {
        const t = clamp01((f - p.at - i * stagger) / dur);
        if (f < p.at + i * stagger) return null;
        const e = easeOut(t);
        const it = italic[i] ?? false;
        // the developing print: overexposed (near white) and soft, darkening into its tone; on dark the "white" is
        // the silver, so the line glows up out of the black instead
        const blur = (1 - e) * 0.12 * px;
        return (
          <div key={i} style={{ ...box({ ...p, y: p.y + (i * leading * px) / H }, W, H), fontFamily: serif(weight, it), fontWeight: weight, fontStyle: it ? 'italic' : 'normal',
            letterSpacing: '-0.01em', color, opacity: clamp01(t * 2.2) * (1 - g), filter: blur > 0.3 ? `blur(${blur.toFixed(1)}px)${shadow ? ` brightness(${(1 + 0.6 * (1 - e)).toFixed(2)})` : ''}` : undefined, textShadow: shadow ? halo(W) : undefined }}>
            {text}
          </div>
        );
      })}
    </>
  );
};

/** A plain line fading up over 8 frames. */
export const Line: React.FC<Place & { text: string; face?: 'serif' | 'type'; italic?: boolean; weight?: number; shadow?: boolean }> = ({ text, face = 'serif', italic = false, weight = 500, color = ARCHIVE.silver, shadow = true, ...p }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  if (f < p.at) return null;
  const t = easeOut((f - p.at) / 8);
  return (
    <div style={{ ...box(p, W, H), fontFamily: face === 'serif' ? serif(weight, italic) : typewriter(weight), fontWeight: weight, fontStyle: italic ? 'italic' : 'normal',
      letterSpacing: face === 'type' ? '0.12em' : '-0.005em', color, opacity: t * (1 - gone(f, p.out)), transform: `translateY(${((1 - t) * 0.12 * p.size * W).toFixed(1)}px)`, textShadow: shadow ? halo(W) : undefined }}>
      {face === 'type' ? text.toUpperCase() : text}
    </div>
  );
};

/** A catalogue tag: paper card, dark typewriter ink, a red accession number; drops in (scale 1.12 to 1, turning
 *  from tilt + 4 to tilt) over 7 frames. Box in fractions of W and H, (x, y) its top-left. */
export const Tag: React.FC<{ x: number; y: number; w: number; at: number; no: string; lines: string[]; tilt?: number; size?: number; out?: number }> = ({ x, y, w, at, no, lines, tilt = -2, size = 0.034, out }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const a = f - at;
  if (a < 0) return null;
  const e = easeOut(a / 7);
  const px = size * W;
  return (
    <div style={{ position: 'absolute', left: x * W, top: y * H, width: w * W, padding: `${px * 0.7}px ${px * 0.85}px ${px * 0.8}px`, boxSizing: 'border-box', background: ARCHIVE.paper,
      backgroundImage: `linear-gradient(180deg, rgba(255,255,255,0.25), rgba(120,90,40,0.12))`, color: ARCHIVE.ink, fontFamily: typewriter(400), fontSize: px, lineHeight: 1.35,
      transform: `rotate(${(tilt + 4 * (1 - e)).toFixed(2)}deg) scale(${(1.12 - 0.12 * e).toFixed(4)})`, transformOrigin: '10% 0%', opacity: clamp01(a / 3) * (1 - gone(f, out)),
      boxShadow: `${0.004 * W}px ${0.01 * W}px ${0.025 * W}px rgba(0,0,0,0.55)` }}>
      {/* the string hole */}
      <div style={{ position: 'absolute', right: px * 0.7, top: px * 0.6, width: px * 0.7, height: px * 0.7, borderRadius: '50%', background: ARCHIVE.umber, boxShadow: `0 0 0 ${px * 0.12}px ${ARCHIVE.paperDark}` }} />
      <div style={{ fontFamily: typewriter(700), fontWeight: 700, color: ARCHIVE.stamp, letterSpacing: '0.08em', marginBottom: px * 0.3 }}>{no}</div>
      {lines.map((l, i) => <div key={i} style={{ whiteSpace: 'pre' }}>{l}</div>)}
    </div>
  );
};

/** A dark scrim behind light type: from the bottom (or top) of the frame, `reach` of the height. */
export const Scrim: React.FC<{ from?: 'bottom' | 'top'; reach?: number; strength?: number }> = ({ from = 'bottom', reach = 0.45, strength = 0.8 }) => (
  <AbsoluteFill style={{ pointerEvents: 'none', background: `linear-gradient(${from === 'bottom' ? '0deg' : '180deg'}, rgba(10,8,6,${strength}) 0%, rgba(10,8,6,${(strength * 0.55).toFixed(2)}) ${(reach * 55).toFixed(0)}%, rgba(10,8,6,0) ${(reach * 100).toFixed(0)}%)` }} />
);
